import{a as e,o as t}from"./jsx-runtime-BXNj1hB7.js";function n(e,t,n,r){return{id:e,title:t,paragraphs:n,bullets:r}}var r=[n(`overview`,e(`科學資產代幣（SAT）`,`Scientific Asset Tokens (SAT)`,`科学アセットトークン（SAT）`,`Wissenschaftliche Asset-Tokens (SAT)`),[e(`SAT（Scientific Asset Token，科學資產代幣）是 MCurator 用於登錄、追溯與授權流通「科學資產」的數位身分框架。科學資產包括博物館或研究機構標本、田野憑證（voucher）、數位圖版、化石與古生物教學圖版、植物標本掃描、可引用之多樣性紀錄，以及附帶結構化後設資料的研究物件。SAT 的設計核心是科學可追溯性、資料完整性與明示授權，而非加密貨幣投機、金融商品包裝或一般 NFT 收藏品炒作。`,`SAT (Scientific Asset Token) is MCurator's digital identity framework for registering, tracing, and licensing scientific assets—including museum specimens, field vouchers, digital plates, fossil teaching plates, botanical scans, citable biodiversity records, and research objects with structured metadata. SAT prioritizes scientific traceability, data integrity, and explicit licensing—not crypto speculation, financial packaging, or generic NFT collectibles.`,`SAT（Scientific Asset Token、科学アセットトークン）は、MCuratorが科学アセットの登録、トレース、ライセンス流通を行うためのデジタルアイデンティティ・フレームワークです。対象には博物館・研究機関の標本、野外バウチャー、デジタル図版、化石・古生物の教育用図版、植物標本スキャン、引用可能な生物多様性記録、構造化メタデータ付きの研究オブジェクトが含まれます。SATの設計の中核は、暗号通貨投機、金融商品化、一般的なNFTコレクションではなく、科学的トレーサビリティ、データ完全性、明示的ライセンスです。`,`SAT (Scientific Asset Token) ist der digitale Identitätsrahmen von MCurator für Registrierung, Rückverfolgung und Lizenzierung wissenschaftlicher Assets — darunter Museumspräparate, Geländevoucher, digitale Tafeln, fossile Lehrtafeln, botanische Scans, zitierbare Biodiversitätsdatensätze und Forschungsobjekte mit strukturierten Metadaten. SAT stellt wissenschaftliche Rückverfolgbarkeit, Datenintegrität und ausdrückliche Lizenzierung in den Vordergrund — nicht Kryptospekulation, Finanzverpackung oder allgemeine NFT-Sammelobjekte.`),e(`每一筆 SAT 擁有唯一 SAT ID，並可連結標本護照（Specimen Passport）、追加式來源履歷（provenance）、保管權轉移紀錄、授權類型與（若賣家明示）實體標本移交條款。SAT 可視為「科學資產的護照＋帳本」：護照供人類可讀展示與引用；帳本供機器可稽核之事件鏈。`,`Each SAT has a unique SAT ID and may link to a Specimen Passport, append-only provenance, custody transfers, license type, and—when explicitly stated—physical specimen terms. Think of SAT as passport plus ledger: human-readable for display and citation; machine-auditable for event chains.`,`各SATには一意のSAT IDがあり、標本パスポート、追記のみのprovenance、保管権移転記録、ライセンス種別、（売主が明示した場合）実物標本の移転条件と連携できます。SATは「科学アセットのパスポート＋台帳」と考えてください。パスポートは人間が読める展示・引用用、台帳は機械監査可能なイベントチェーン用です。`,`Jedes SAT besitzt eine eindeutige SAT-ID und kann mit einem Präparat-Pass, einer nur anhängbaren Herkunft, Verwahrungsübertragungen, dem Lizenztyp und — wenn ausdrücklich angegeben — Bedingungen zum physischen Präparat verknüpft werden. Betrachten Sie SAT als Pass plus Hauptbuch: menschenlesbar für Anzeige und Zitation; maschinenprüfbar für Ereignisketten.`),e(`【台灣法規定位（摘要）】SAT 本身並非我國法令定義之「貨幣」「有價證券」或「存款」；示範環境不提供投資報酬承諾。涉及實體標本、影像、個資或跨國移動時，仍可能受《野生動物保育法》《文化資產保存法》《個人資料保護法》《著作權法》《消費者保護法》及進出口／檢疫等規範約束，須由交易當事人自行確認。`,`[Taiwan law — summary] SAT is not defined under Taiwan law as currency, securities, or deposits; the demo makes no investment promises. Physical specimens, imagery, personal data, or cross-border movement may still fall under the Wildlife Conservation Act, Cultural Heritage Preservation Act, PDPA, Copyright Act, Consumer Protection Act, and import/export or quarantine rules—parties must confirm applicability themselves.`,`【台湾法規（概要）】SAT自体は台湾法上の「通貨」「有価証券」「預金」には該当しません。デモ環境では投資リターンを約束しません。実物標本、画像、個人データ、国境を越える移動には、野生動物保育法、文化資産保存法、個人データ保護法、著作権法、消費者保護法、輸出入・検疫規制が適用される場合があり、当事者が各自確認する必要があります。`,`[Taiwanisches Recht — Kurzfassung] SAT ist nach taiwanischem Recht nicht als Währung, Wertpapier oder Einlage definiert; die Demo gibt keine Anlageversprechen. Physische Präparate, Bildmaterial, personenbezogene Daten oder grenzüberschreitende Verbringung können weiterhin dem Wildlife Conservation Act, dem Cultural Heritage Preservation Act, der PDPA, dem Copyright Act, dem Consumer Protection Act sowie Ein- und Ausfuhr- oder Quarantäneregeln unterliegen. Die Parteien müssen die Anwendbarkeit selbst prüfen.`),e(`【國際法規定位（摘要）】跨境標本或數位資料流通可能涉及 CITES（華盛頓公約）、《生物多樣性公約》（CBD）及《名古屋議定書》所規範之遺傳資源與傳統知識（ABS／惠益分享）、WIPO／《伯恩公約》體系下之著作權，以及歐盟 GDPR 等資料保護規則（視資料主體與處理地而定）。SAT 元資料可對齊 Darwin Core 等國際社群標準，但不自動取代各國許可或機構典藏政策。`,`[International law — summary] Cross-border specimens or data may implicate CITES, the Convention on Biological Diversity (CBD) and Nagoya Protocol (ABS / benefit-sharing), copyright under Berne / WIPO, and GDPR or similar regimes depending on subjects and processing. SAT metadata may align with Darwin Core and community standards but does not replace national permits or institutional policies.`,`【国際法規（概要）】国境を越える標本やデータの流通には、CITES、生物多様性条約（CBD）、名古屋議定書（ABS／惠益分享）、ベルヌ／WIPO体制下の著作権、EU GDPRなどのデータ保護規則が関わる場合があります。SATメタデータはDarwin Coreなどの国際標準に整合できますが、各国の許可や機関のコレクション方針を自動的に置き換えるものではありません。`,`[Internationales Recht — Kurzfassung] Grenzüberschreitende Präparate oder Daten können CITES, das Übereinkommen über die biologische Vielfalt (CBD) und das Nagoya-Protokoll (ABS / Vorteilsausgleich), Urheberrecht nach Berne / WIPO sowie die GDPR oder vergleichbare Regelungen betreffen — abhängig von Betroffenen und Verarbeitung. SAT-Metadaten können an Darwin Core und Gemeinschaftsstandards angeglichen werden, ersetzen aber keine nationalen Genehmigungen und keine institutionellen Richtlinien.`),e(`【非法律意見聲明】本頁為產品與合規教育說明，不構成法律意見、公證、投資建議或政府背書。正式交易前，賣方、買方、保管機構及跨國移動之物流／報關／檢疫顧問應就個案取得合格法律與科學專業意見。`,`[Not legal advice] This page is product and compliance education—not legal advice, notarization, investment advice, or government endorsement. Before live transactions, sellers, buyers, custodians, and logistics / customs / quarantine advisors should obtain qualified legal and scientific advice for each case.`,`【法的助言ではありません】本ページは製品・コンプライアンス教育用であり、法的助言、公証、投資助言、政府の保証ではありません。正式取引前に、売主、買主、保管機関、物流／通関／検疫アドバイザーは個別案件について適格な法律・科学の専門意見を取得してください。`,`[Kein Rechtsrat] Diese Seite dient der Produkt- und Compliance-Aufklärung — sie ist kein Rechtsrat, keine Beurkundung, keine Anlageberatung und keine staatliche Billigung. Vor echten Transaktionen sollten Verkäuferinnen und Verkäufer, Käuferinnen und Käufer, Verwahrende sowie Beraterinnen und Berater für Logistik, Zoll und Quarantäne für jeden Einzelfall qualifizierten rechtlichen und wissenschaftlichen Rat einholen.`)],[e(`唯一 SAT ID 與結構化科學後設資料`,`Unique SAT ID with structured scientific metadata`,`構造化された科学メタデータを持つ一意のSAT ID`,`Eindeutige SAT-ID mit strukturierten wissenschaftlichen Metadaten`),e(`標本護照與 QR／CSV／JSON 匯出`,`Specimen passport with QR / CSV / JSON export`,`QR／CSV／JSONエクスポート対応の標本パスポート`,`Präparat-Pass mit QR- / CSV- / JSON-Export`),e(`追加式 provenance 時間軸`,`Append-only provenance timeline`,`追記のみのprovenanceタイムライン`,`Nur anhängbare Herkunftszeitachse`),e(`明示授權與權利摘要`,`Explicit license and rights summary`,`明示的なライセンスと権利の概要`,`Ausdrückliche Lizenz und Rechtekurzfassung`),e(`可選實體標本綁定（須 listing 明示）`,`Optional physical binding (must be stated on listing)`,`任意の実物紐付け（listingに明記必須）`,`Optionale physische Bindung (muss im Angebot angegeben sein)`)]),n(`metadata`,e(`已驗證元資料`,`Verified metadata`,`検証済みメタデータ`,`Verifizierte Metadaten`),[e(`「已驗證元資料」指在平台工作流中已通過最低完整度、一致性與權利摘要檢查之科學欄位集合，例如：學名與分類階層、SAT ID、產地（含模糊化策略）、採集或登錄日期、採集者（若公開）、hero-passport 影像、尺度標、驗證徽章、授權類型、下載條件、實體綁定標示及外部資料庫引用（GBIF、Catalogue of Life 等）。驗證代表資料就緒度與工作流里程碑，不代表學界定名之終局裁定、政府鑑定或法院可採信之鑑識結論。`,`"Verified metadata" means scientific fields that passed minimum completeness, consistency, and rights-summary checks—e.g., taxonomy, SAT ID, locality (with obfuscation strategy), dates, collector (if public), hero-passport imagery, scale bar, verification badges, license type, download terms, physical binding flag, and external citations (GBIF, Catalogue of Life, etc.). Verification marks readiness and workflow milestones—not final taxonomic authority, government appraisal, or court-admissible expert conclusions.`,`「検証済みメタデータ」とは、最低限の完全性、一貫性、権利概要チェックを通過した科学フィールドの集合です。例：分類階層、SAT ID、採集地（曖昧化戦略含む）、日付、採集者（公開時）、hero-passport画像、スケールバー、検証バッジ、ライセンス種別、ダウンロード条件、実物紐付けフラグ、外部引用（GBIF、Catalogue of Lifeなど）。検証はデータの準備度とワークフローのマイルストーンを示し、学術的な最終同定、政府鑑定、裁判所が採用する鑑識結論と同等ではありません。`,`„Verifizierte Metadaten“ bezeichnet wissenschaftliche Felder, die Mindestprüfungen zu Vollständigkeit, Konsistenz und Rechtekurzfassung bestanden haben — etwa Taxonomie, SAT-ID, Fundort (mit Unkenntlichmachungsstrategie), Daten, Sammlerin bzw. Sammler (falls öffentlich), Hero-Pass-Bilder, Maßstabsleiste, Prüfzeichen, Lizenztyp, Downloadbedingungen, Kennzeichen physischer Bindung und externe Zitate (GBIF, Catalogue of Life usw.). Die Verifizierung kennzeichnet Bereitschaft und Workflow-Meilensteine — nicht die endgültige taxonomische Autorität, keine staatliche Bewertung und keine gerichtlich verwertbaren Gutachten.`),e(`完整度（completeness）由規則引擎依必填欄位、影像品質、診斷特徵可見度、佐證文件（採集許可、館藏登錄證明、CITES 副本摘要等，若賣家提供）計算。館員可覆核並調整正式驗證狀態；買方應將驗證視為盡職調查起點，而非風險終點。`,`Completeness scores come from required fields, image quality, visible diagnostic features, and supporting documents (collection permits, accession proofs, CITES summary copies if provided). Curators may review official verification states; buyers should treat verification as due-diligence starting point, not end of risk review.`,`完全度スコアは、必須項目、画像品質、診断形質の可視性、補助書類（採集許可、受入証明、CITES写しの概要など、売主が提供した場合）から算出されます。キュレーターが正式な検証状態を再審できます。買主は検証をデューデリジェンスの出発点とし、リスク審査の終点とは考えないでください。`,`Vollständigkeitswerte ergeben sich aus Pflichtfeldern, Bildqualität, sichtbaren Diagnosemerkmalen und Belegen (Sammelgenehmigungen, Zugangsnachweise, CITES-Kurzfassungen, sofern bereitgestellt). Kuratorinnen und Kuratoren können den förmlichen Verifizierungsstatus prüfen. Käuferinnen und Käufer sollten die Verifizierung als Ausgangspunkt der Sorgfaltsprüfung behandeln, nicht als Ende der Risikoprüfung.`),e(`【台灣 — 個人資料】採集者姓名、聯絡方式、精確 GPS、原住民傳統領域或稀有物種棲地等，可能構成《個人資料保護法》所稱個人資料或涉及原住民／文化敏感資訊。上架時應依告知義務、特定目的、最小必要、模糊化或延遲公開等原則處理；示範環境請勿輸入真實敏感個資。`,`[Taiwan — personal data] Collector names, contact details, precise GPS, indigenous territories, or rare-species localities may be PDPA personal data or culturally sensitive. Apply notice, purpose limitation, minimization, obfuscation, or delayed publication; do not enter real sensitive data in the demo.`,`【台湾 — 個人データ】採集者名、連絡先、正確なGPS、先住民の伝統領域、希少種の生息地は、個人データ保護法上の個人データまたは文化的に機微な情報となる場合があります。告知、目的限定、最小化、曖昧化、遅延公開の原則を適用してください。デモ環境では実際の機微な個人情報を入力しないでください。`,`[Taiwan — personenbezogene Daten] Namen von Sammlerinnen und Sammlern, Kontaktdaten, präzises GPS, indigene Territorien oder Fundorte seltener Arten können personenbezogene Daten nach der PDPA oder kulturell sensible Angaben sein. Wenden Sie Hinweis, Zweckbindung, Datenminimierung, Unkenntlichmachung oder verzögerte Veröffentlichung an. Geben Sie in der Demo keine echten sensiblen Daten ein.`),e(`【國際 — 資料保護與開放科學】涉及歐盟資料主體或於歐盟處理時，可能適用 GDPR 之合法性基礎、資料主體權利與跨境傳輸機制。對外發布或匯入 GBIF 等國際資料庫時，須符合該平台之授權條款（如 CC0、CC BY）及國家／機構開放資料政策；SAT 匯出欄位規劃對齊 Darwin Core（dwc:）以利互通。`,`[International — data protection & open science] EU subjects or processing in the EU may trigger GDPR lawful bases, data-subject rights, and transfer mechanisms. Publishing to GBIF or similar requires platform license terms (CC0, CC BY, etc.) and national/institutional open-data policies. SAT export fields align with Darwin Core (dwc:) for interoperability.`,`【国際 — データ保護とオープンサイエンス】EUのデータ主体またはEUでの処理には、GDPRの合法性根拠、データ主体の権利、越境移転の仕組みが適用される場合があります。GBIFなどへの公開は、プラットフォームのライセンス条項（CC0、CC BYなど）と国・機関のオープンデータ方針に従う必要があります。SATエクスポート項目は相互運用のためDarwin Core（dwc:）に整合します。`,`[International — Datenschutz und Open Science] Betroffene in der EU oder Verarbeitung in der EU können Rechtsgrundlagen, Betroffenenrechte und Übermittlungsmechanismen der GDPR auslösen. Die Veröffentlichung bei GBIF oder vergleichbaren Stellen erfordert die Lizenzbedingungen der Plattform (CC0, CC BY usw.) sowie nationale bzw. institutionelle Open-Data-Richtlinien. SAT-Exportfelder sind für die Interoperabilität an Darwin Core (dwc:) angeglichen.`)],[e(`核心：學名、SAT ID、類別、產地、保管者、授權摘要`,`Core: scientific name, SAT ID, category, locality, custodian, rights summary`,`コア：学名、SAT ID、カテゴリ、採集地、保管者、権利概要`,`Kern: wissenschaftlicher Name, SAT-ID, Kategorie, Fundort, Verwahrende, Rechtekurzfassung`),e(`影像：hero-passport、尺度標、可選 EXIF（依隱私政策）`,`Imagery: hero-passport, scale bar, optional EXIF per privacy policy`,`画像：hero-passport、スケールバー、プライバシーポリシーに応じた任意EXIF`,`Bilder: Hero-Pass, Maßstabsleiste, optionales EXIF gemäß Datenschutzrichtlinie`),e(`合規摘要：CITES 狀態欄位、採集許可引用、ABS／惠益分享聲明（若適用）`,`Compliance summary: CITES status field, permit citations, ABS/benefit-sharing statement if applicable`,`コンプライアンス概要：CITESステータス欄、許可証引用、該当時のABS／惠益分享声明`,`Compliance-Kurzfassung: CITES-Statusfeld, Genehmigungszitate, ABS-/Vorteilsausgleichserklärung falls zutreffend`),e(`外部對齊：GBIF、CoL、機構典藏號交叉引用`,`External alignment: GBIF, CoL, institutional catalog cross-refs`,`外部連携：GBIF、CoL、機関コレクション番号の相互参照`,`Externe Angleichung: GBIF, CoL, institutionelle Katalogquerverweise`)]),n(`passport`,e(`標本護照（Specimen Passport）`,`Specimen Passport`,`標本パスポート`,`Präparat-Pass`),[e(`標本護照是 SAT 的「可攜式科學身分證」：以卡片或數位頁面呈現學名、產地、採集或登錄日期、保管者、驗證狀態、授權摘要、SAT ID、MC-PASS 等護照編號，以及（若適用）實體標本綁定與 CITES／許可摘要。QR 碼指向可解析之 SAT 紀錄，供展覽、教室、出版物或法庭／仲裁案件中之引用查核（是否採信由主管機關或法院決定，平台不作保證）。`,`The Specimen Passport is the portable scientific identity for an SAT: card or digital view with scientific name, locality, dates, custodian, verification status, license summary, SAT ID, MC-PASS-style numbers, and—where applicable—physical binding and CITES/permit summaries. QR codes resolve to SAT records for exhibition, teaching, publications, or dispute review (admissibility is for authorities or courts—platform makes no guarantee).`,`標本パスポートはSATの「携帯型科学身分証」です。カードまたはデジタル画面で学名、採集地、日付、保管者、検証状態、ライセンス概要、SAT ID、MC-PASS形式の番号、（該当時）実物紐付けとCITES／許可概要を表示します。QRコードは展示、教育、出版物、紛争審査用にSAT記録へ解決します（採用可否は当局または裁判所が判断し、プラットフォームは保証しません）。`,`Der Präparat-Pass ist die tragbare wissenschaftliche Identität eines SAT: Karte oder digitale Ansicht mit wissenschaftlichem Namen, Fundort, Daten, Verwahrenden, Verifizierungsstatus, Lizenzkurzfassung, SAT-ID, MC-PASS-Nummern und — sofern zutreffend — physischer Bindung sowie CITES-/Genehmigungskurzfassungen. QR-Codes lösen zu SAT-Akten auf, für Ausstellung, Lehre, Publikationen oder Streitprüfung (die Verwertbarkeit entscheiden Behörden oder Gerichte — die Plattform gibt keine Garantie).`),e(`護照影像與 hero-passport 照片代表教學或典藏級視覺憑證。市集僅顯示具真實 hero-passport 照片之項目，不以占位圖或第三方圖庫替代。影像之著作權／鄰接權仍歸原權利人；護照展示不等同於取得超出 listing 授權之複製或改作權。`,`Passport and hero-passport photos are teaching- or collection-grade visual vouchers. The marketplace lists only real hero-passport photos—no placeholders or stock images. Copyright in images remains with rights holders; passport display does not grant reproduction or adaptation beyond the listing license.`,`パスポートとhero-passport写真は教育・コレクション級の視覚バウチャーです。マーケットプレイスは実際のhero-passport写真のみを表示し、プレースホルダーやストック画像は使用しません。画像の著作権は原権利者に帰属します。パスポート表示はlistingライセンスを超える複製・改作権を付与しません。`,`Pass- und Hero-Pass-Fotos sind visuelle Nachweise in Lehr- oder Sammlungsqualität. Der Marktplatz listet nur echte Hero-Pass-Fotos — keine Platzhalter oder Stockbilder. Urheberrechte an Bildern verbleiben bei den Rechteinhabern; die Pass-Anzeige gewährt keine Vervielfältigung oder Bearbeitung über die Angebotslizenz hinaus.`),e(`【台灣 — 引用與標示】學術或教育引用建議標示：SAT ID、學名、產地（若公開）、保管者、授權類型、存取日期及 MCurator／SAT 解析 URL。涉及《文化資產保存法》之古生物化石、考古標本或指定文化資產，護照本身不取代主管機關之指定、移出或出口許可。`,`[Taiwan — citation & labeling] Cite SAT ID, scientific name, locality (if public), custodian, license type, access date, and resolvable URL. For fossils, archaeological specimens, or designated heritage under the Cultural Heritage Preservation Act, the passport does not replace designation, export, or transfer permits from competent authorities.`,`【台湾 — 引用と表示】SAT ID、学名、採集地（公開時）、保管者、ライセンス種別、アクセス日、解決可能なURLを記載することを推奨します。文化資産保存法の化石、考古標本、指定文化資産について、パスポート自体は指定、移出、輸出許可の代替にはなりません。`,`[Taiwan — Zitation und Kennzeichnung] Geben Sie SAT-ID, wissenschaftlichen Namen, Fundort (falls öffentlich), Verwahrende, Lizenztyp, Zugriffsdatum und eine auflösbare URL an. Für Fossilien, archäologische Präparate oder ausgewiesenes Kulturerbe nach dem Cultural Heritage Preservation Act ersetzt der Pass keine Ausweisung, Ausfuhr oder Übertragungsgenehmigung der zuständigen Behörden.`),e(`【國際 — 引用標準】建議對齊 DataCite、Darwin Core 與 GBIF 引用實務；跨國出版或資料庫匯入時，應同時遵守期刊、博物館與資料庫之 metadata 與授權政策。護照 QR 作為持久識別符（persistent identifier）輔助工具，正式持久性以平台公告之解析政策為準。`,`[International — citation] Align with DataCite, Darwin Core, and GBIF citation practice. Cross-border publication or database ingestion must follow journal, museum, and repository metadata and license policies. Passport QR aids persistent identification; official persistence follows platform resolution policy.`,`【国際 — 引用】DataCite、Darwin Core、GBIFの引用慣行に整合してください。国境を越える出版やデータベース取り込みは、学術誌、博物館、リポジトリのメタデータ・ライセンス方針に従う必要があります。パスポートQRは永続識別子の補助です。正式な永続性はプラットフォームの解決ポリシーに従います。`,`[International — Zitation] Richten Sie sich an DataCite, Darwin Core und GBIF-Zitierpraxis aus. Grenzüberschreitende Publikation oder Datenbankaufnahme muss Metadaten- und Lizenzrichtlinien von Zeitschriften, Museen und Repositorien befolgen. Der Pass-QR unterstützt persistente Identifikation; die förmliche Persistenz folgt der Auflösungsrichtlinie der Plattform.`)],[e(`正面：標本影像、SAT ID、學名、驗證徽章`,`Front: specimen image, SAT ID, scientific name, verification badges`,`表面：標本画像、SAT ID、学名、検証バッジ`,`Vorderseite: Präparatbild, SAT-ID, wissenschaftlicher Name, Prüfzeichen`),e(`背面：QR、授權摘要、引用欄位、許可摘要（示範）`,`Back: QR, license summary, citation fields, permit summary (demo)`,`裏面：QR、ライセンス概要、引用欄、許可証概要（デモ）`,`Rückseite: QR, Lizenzkurzfassung, Zitatfelder, Genehmigungskurzfassung (Demo)`),e(`匯出：QR／CSV／JSON（依資產就緒度）`,`Export: QR / CSV / JSON (per asset readiness)`,`エクスポート：QR／CSV／JSON（アセットの準備状況による）`,`Export: QR / CSV / JSON (je nach Asset-Bereitschaft)`)]),n(`provenance`,e(`來源履歷與保管權`,`Provenance & custody`,`由来履歴と保管権`,`Herkunft und Verwahrung`),[e(`Provenance（來源履歷）以追加式時間軸記錄生命週期事件：採集、入館、修復、數位化、SAT 鑄造（mint）、驗證、上架、成交、保管權轉移、再授權或爭議標記等。事件一經寫入，一般使用者不得覆寫或刪除，以維持稽核可讀性；更正須以「追加更正事件」方式留痕，而非靜默改寫。`,`Provenance is an append-only timeline: collection, accession, preparation, digitization, SAT minting, verification, listing, settlement, custody transfer, re-licensing, or dispute flags. Ordinary users cannot rewrite or delete history; corrections should be new append-only correction events, not silent edits.`,`Provenanceは追記のみのタイムラインで、採集、受入、整備、デジタル化、SATミント、検証、出品、成約、保管権移転、再ライセンス、紛争フラグなどを記録します。一般ユーザーは履歴を上書き・削除できません。訂正は追記イベントとして残し、静かな改変は行いません。`,`Herkunft ist eine nur anhängbare Zeitachse: Sammlung, Zugang, Präparation, Digitalisierung, SAT-Prägung, Verifizierung, Angebot, Abwicklung, Verwahrungsübertragung, erneute Lizenzierung oder Streitkennzeichen. Gewöhnliche Nutzerinnen und Nutzer können die Historie weder überschreiben noch löschen; Korrekturen erfolgen als neue, nur anhängbare Korrekturereignisse, nicht als stille Änderungen.`),e(`保管權（custody）指誰負責標本或數位紀錄之保存、管理與對外代表；不等同於完整所有權、著作權或無限制處分權。SAT 成交更新平台紀錄中之保管人與授權關係，不自動完成《民法》上動產移轉、博物館 deaccession 程序或跨國貨物所有權變更。`,`Custody is who holds, cares for, and represents the specimen or digital record—not necessarily full ownership, copyright, or unlimited disposal rights. SAT settlement updates custodian and license on the platform; it does not automatically complete civil transfer of movable property, museum deaccession, or cross-border title changes.`,`保管権（custody）は、標本またはデジタル記録の保存・管理・対外代表の責任者を指し、必ずしも完全な所有権、著作権、無制限の処分権を意味しません。SAT成約はプラットフォーム上の保管者とライセンスを更新しますが、民法上の動産移転、博物館のdeaccession、国境を越える所有権変更を自動的に完了しません。`,`Verwahrung bezeichnet, wer das Präparat oder die digitale Akte hält, betreut und nach außen vertritt — nicht zwingend volles Eigentum, Urheberrecht oder unbeschränktes Verfügungsrecht. Die SAT-Abwicklung aktualisiert Verwahrende und Lizenz auf der Plattform; sie vollzieht nicht automatisch die zivilrechtliche Übertragung beweglicher Sachen, ein Museums-Deaccession oder grenzüberschreitende Eigentumsänderungen.`),e(`【台灣 — 野生動植物與文化資產】受《野生動物保育法》保護之野生動物產製品、獵捕或買賣限制物種，其採集、持有、移轉或展示須符合主管機關規定及許可；珍貴稀有植物、國家公園或保護區內採集亦可能受《國家公園法》等限制。古生物化石、考古遺物或指定文化資產受《文化資產保存法》規範，provenance 應保留許可、登錄、移出或借出文件摘要。`,`[Taiwan — wildlife & heritage] Wildlife and products under the Wildlife Conservation Act, harvest or trade restrictions, and collection in national parks may require permits. Fossils, archaeological finds, and designated heritage fall under the Cultural Heritage Preservation Act; provenance should retain permit, registration, export, or loan document summaries.`,`【台湾 — 野生生物と文化資産】野生動物保育法の保護対象や採集・取引制限、国立公園内の採集には許可が必要な場合があります。化石、考古遺物、指定文化資産は文化資産保存法の対象です。provenanceには許可、登録、移出、貸出書類の概要を残してください。`,`[Taiwan — Wildtiere und Kulturerbe] Wildtiere und Erzeugnisse nach dem Wildlife Conservation Act, Ernte- oder Handelsbeschränkungen sowie das Sammeln in Nationalparks können Genehmigungen erfordern. Fossilien, archäologische Funde und ausgewiesenes Kulturerbe unterliegen dem Cultural Heritage Preservation Act; die Herkunft sollte Kurzfassungen von Genehmigung, Registrierung, Ausfuhr oder Leihvertrag behalten.`),e(`【國際 — CITES 與 ABS】CITES 附錄物種之國際貿易須符合出口／再出口／進口許可證要求；SAT provenance 可記載許可證號、核發國、有效期與物種學名對照，但不代為申請或驗證。CBD《名古屋議定書》要求遺傳資源與傳統知識之利用可能須取得 Prior Informed Consent（PIC）與 Mutually Agreed Terms（MAT）；跨境研究或商業利用前應完成 ABS 盡職調查。`,`[International — CITES & ABS] CITES Appendix trade requires export/re-export/import permits; provenance may record permit numbers, issuing country, validity, and taxonomy cross-checks—the platform does not apply for or validate permits. The Nagoya Protocol may require PIC and MAT for genetic resources and traditional knowledge; complete ABS due diligence before cross-border research or commercial use.`,`【国際 — CITESとABS】CITES附属書の国際取引には輸出／再輸出／輸入許可が必要です。provenanceに許可番号、発行国、有効期間、種の照合を記録できますが、プラットフォームは許可の申請・検証を行いません。名古屋議定書では遺伝資源と伝統的知識の利用にPICとMATが必要な場合があります。国境を越える研究・商用利用前にABSデューデリジェンスを完了してください。`,`[International — CITES und ABS] Der Handel nach CITES-Anhang erfordert Ausfuhr-, Wiederausfuhr- und Einfuhrgenehmigungen; die Herkunft kann Genehmigungsnummern, ausstellendes Land, Gültigkeit und taxonomische Gegenprüfungen festhalten — die Plattform beantragt und prüft Genehmigungen nicht. Das Nagoya-Protokoll kann PIC und MAT für genetische Ressourcen und traditionelles Wissen verlangen; schließen Sie die ABS-Sorgfaltsprüfung vor grenzüberschreitender Forschung oder kommerzieller Nutzung ab.`)],[e(`典型鏈：Collected → Accessioned → Digitized → Minted → Listed → Transferred`,`Typical chain: Collected → Accessioned → Digitized → Minted → Listed → Transferred`,`典型的な連鎖：採集 → 受入 → デジタル化 → Mint → 出品 → 移転`,`Typische Kette: Gesammelt → Akzessioniert → Digitalisiert → Geprägt → Gelistet → Übertragen`),e(`機構典藏號與 SAT ID 並存、交叉引用`,`Institutional catalog numbers coexist with SAT ID`,`機関コレクション番号とSAT IDの併存・相互参照`,`Institutionelle Katalognummern bestehen neben der SAT-ID und werden querverwiesen`),e(`爭議或更正：追加事件留痕，不刪除歷史`,`Disputes/corrections: append-only events, no history deletion`,`紛争／訂正：追記イベントのみ、履歴削除なし`,`Streit oder Korrektur: nur anhängbare Ereignisse, keine Löschung der Historie`)]),n(`rights`,e(`授權、使用權利與交易內容`,`Licensing, usage rights & acquisition`,`ライセンス、利用権、取得`,`Lizenzierung, Nutzungsrechte und Erwerb`),[e(`每筆上架應在成交前明示授權類型（學術引用、教育使用、展覽使用、商業授權、典藏級有限版本等）及禁止事項。買方取得的是 listing 所載範圍內之數位紀錄與元資料使用權，而非自動取得標本完整著作權、專利、商標、無限制商業化權、學名命名優先權或科學鑑定保證。`,`Each listing must state license type (academic citation, education, exhibition, commercial, collector edition, etc.) and restrictions before acquisition. Buyers receive digital record and metadata usage within that license—not automatic full copyright, patents, trademarks, unlimited commercialization, nomenclatural priority, or scientific warranty.`,`各listingは成約前にライセンス種別（学術引用、教育、展示、商用、コレクター版など）と禁止事項を明示する必要があります。買主が得るのはそのライセンス範囲内のデジタル記録とメタデータの利用権であり、標本の完全な著作権、特許、商標、無制限の商用化、命名優先権、科学的保証を自動的に取得するものではありません。`,`Jedes Angebot muss vor dem Erwerb Lizenztyp (akademische Zitation, Bildung, Ausstellung, kommerziell, Sammlerausgabe usw.) und Verbote ausdrücklich angeben. Käuferinnen und Käufer erhalten Nutzungsrechte an digitaler Akte und Metadaten innerhalb dieser Lizenz — nicht automatisch volles Urheberrecht, Patente, Marken, unbeschränkte Kommerzialisierung, nomenklatorische Priorität oder eine wissenschaftliche Gewährleistung.`),e(`【台灣 — 著作權與消費者保護】標本照片、圖版、描述文字之著作權依《著作權法》屬創作人或約定之權利人；SAT 移轉不當然移轉著作財產權，除非書面另有約定。對一般消費者之網路交易，可能適用《消費者保護法》之資訊揭露、七日猶豫期（若適用法定範圍）及爭議處理；正式上線條款將載明適用與排除情形。`,`[Taiwan — copyright & consumer law] Image and text copyright under the Copyright Act belongs to creators or agreed rights holders; SAT transfer does not automatically assign copyright unless written agreement says so. B2C online sales may trigger Consumer Protection Act disclosure, cooling-off where legally applicable, and dispute channels—live terms will specify scope and exclusions.`,`【台湾 — 著作権と消費者保護】画像・文章の著作権は著作権法に基づき創作者または合意された権利者に帰属します。SAT移転は書面合意がない限り著作財産権を自動移転しません。一般消費者向けオンライン取引には消費者保護法の情報開示、法定の場合のクーリングオフ、紛争処理が適用される可能性があります。正式条項で適用範囲と除外を明記します。`,`[Taiwan — Urheberrecht und Verbraucherschutz] Urheberrecht an Bild und Text nach dem Copyright Act steht den Schöpferinnen und Schöpfern oder vereinbarten Rechteinhabern zu; die SAT-Übertragung tritt das Urheberrecht nicht automatisch ab, sofern keine schriftliche Vereinbarung dies vorsieht. Online-Verkäufe an Verbraucherinnen und Verbraucher können Informationspflichten nach dem Consumer Protection Act, ein Widerrufsrecht im gesetzlich anwendbaren Rahmen und Streitwege auslösen — die förmlichen Bedingungen werden Umfang und Ausschlüsse festlegen.`),e(`【國際 — 著作權與開放授權】跨境利用須尊重 Berne 公約最低保護標準、WIPO Treaty 及目的地國強制規定。Creative Commons（CC BY、CC BY-NC、CC0 等）常見於學術與 biodiversity 資料；listing 授權應與 CC 條款一致或更嚴格，並標示 Attribution 要求。商業使用、改作、再授權（sublicense）須在 listing 明示允許，否則預設禁止。`,`[International — copyright & open licenses] Cross-border use must respect Berne minimum standards, WIPO treaties, and destination mandatory rules. Creative Commons (CC BY, CC BY-NC, CC0, etc.) is common in academia and biodiversity data; listing licenses should match or be stricter than CC terms with clear attribution. Commercial use, adaptation, and sublicensing require explicit listing permission—otherwise presumed prohibited.`,`【国際 — 著作権とオープンライセンス】国境を越える利用はベルヌ最低基準、WIPO条約、目的地国の強行規定を尊重する必要があります。Creative Commons（CC BY、CC BY-NC、CC0など）は学術・生物多様性データで一般的です。listingライセンスはCC条項と一致するか、それより厳格にし、帰属表示を明確にしてください。商用利用、改作、再ライセンスはlistingで明示的に許可が必要です。なければ原則禁止とみなされます。`,`[International — Urheberrecht und offene Lizenzen] Grenzüberschreitende Nutzung muss die Mindeststandards von Berne, WIPO-Verträge und zwingendes Recht des Bestimmungsstaates achten. Creative Commons (CC BY, CC BY-NC, CC0 usw.) ist in Wissenschaft und Biodiversitätsdaten üblich; Angebotslizenzen sollten den CC-Bedingungen entsprechen oder strenger sein und die Namensnennung klar kennzeichnen. Kommerzielle Nutzung, Bearbeitung und Unterlizenzierung erfordern ausdrückliche Erlaubnis im Angebot — sonst gelten sie als untersagt.`),e(`【實體標本、付款與稅務】含實體標本者，數位 SAT 成交與物流、CITES、檢疫、保險應分開追蹤。付款方式（信用卡、匯款、穩定幣等）由賣家選擇；示範環境為模擬金流。正式環境涉及跨境付款、反洗錢（AML）、認識你的客戶（KYC）及稅務申報時，當事人應遵守台灣《洗錢防制法》、國際制裁名單及當地稅法，平台將於上線條款載明責任分工。`,`[Physical specimens, payments & tax] When physical binding applies, digital settlement and logistics, CITES, quarantine, and insurance are tracked separately. Payment methods are seller-selected; demo payments are simulated. Live cross-border payments may trigger Taiwan AML rules, sanctions screening, KYC, and tax reporting—parties must comply; platform terms will allocate responsibilities at launch.`,`【実物標本、支払い、税務】実物紐付けがある場合、デジタル成約と物流、CITES、検疫、保険は別々に追跡します。支払い方法は売主が選択します。デモ環境の支払いは模擬です。本番の国境を越える支払いには台湾のAML規則、制裁スクリーニング、KYC、税務申告が関わる場合があり、当事者は遵守する必要があります。責任分担は公開時の条項で示します。`,`[Physische Präparate, Zahlungen und Steuern] Bei physischer Bindung werden digitale Abwicklung und Logistik, CITES, Quarantäne und Versicherung getrennt verfolgt. Zahlungsarten wählt die Verkäuferseite; Demo-Zahlungen sind simuliert. Echte grenzüberschreitende Zahlungen können taiwanische AML-Regeln, Sanktionsprüfungen, KYC und Steuererklärungen auslösen — die Parteien müssen einhalten; die Plattformbedingungen werden die Verantwortlichkeiten bei der Einführung zuweisen.`)],[e(`學術引用：論文、教案、展簽須標 SAT ID 與授權`,`Academic citation: papers, teaching, labels with SAT ID and license`,`学術引用：論文、教材、ラベルにSAT IDとライセンスを記載`,`Akademische Zitation: Aufsätze, Lehre, Etiketten mit SAT-ID und Lizenz`),e(`教育／展覽：依 listing 非商業或展覽授權`,`Education/exhibition: per listing non-commercial or exhibition license`,`教育／展示：listingの非商用または展示ライセンスに従う`,`Bildung / Ausstellung: gemäß nichtkommerzieller oder Ausstellungslizenz des Angebots`),e(`商業：僅 listing 明示允許時`,`Commercial: only when explicitly allowed on listing`,`商用：listingで明示的に許可された場合のみ`,`Kommerziell: nur wenn im Angebot ausdrücklich erlaubt`),e(`通常不含：投資報酬、未標示實體、代辦 CITES／報關（除非另議）`,`Often excluded: investment return, unstated physical, CITES/customs agency unless agreed`,`通常除外：投資リターン、未明示の実物、CITES／通関代行（別途合意がない限り）`,`Häufig ausgeschlossen: Anlageertrag, nicht angegebenes Physisches, CITES-/Zollvertretung sofern nicht vereinbart`)])],i=[{q:e(`SAT 是加密貨幣或 NFT 嗎？`,`Is SAT a cryptocurrency or NFT?`,`SATは暗号通貨またはNFTですか？`,`Ist SAT eine Kryptowährung oder ein NFT?`),a:e(`不是。SAT 是科學資產登錄與追溯框架，可選擇性連結區塊鏈紀錄，但非投機性代幣。與一般 NFT 不同：強調標本級後設資料、provenance、明示授權與（可選）實體綁定。依台灣現行法規，SAT 本身不當然構成《銀行法》所定之貨幣或《證券交易法》之有價證券；仍不得進行虛偽投資宣傳。`,`No. SAT is a scientific asset registration and traceability framework and may optionally link to on-chain records—it is not a speculative token. Unlike typical NFTs, it emphasizes specimen-grade metadata, provenance, explicit licensing, and optional physical binding. Under Taiwan law, SAT is not automatically currency under the Banking Act or securities under the Securities and Exchange Act; false investment marketing remains prohibited.`,`いいえ。SATは科学アセットの登録・トレースのフレームワークであり、オプションでオンチェーン記録と連携できますが、投機的トークンではありません。一般的なNFTと異なり、標本級メタデータ、provenance、明示的ライセンス、（任意の）実物紐付けを重視します。台湾法上、SATは銀行法の通貨や証券取引法の有価証券に自動的には該当しません。虚偽の投資宣伝は禁止されています。`,`Nein. SAT ist ein Rahmen für die Registrierung und Rückverfolgung wissenschaftlicher Assets und kann optional mit On-Chain-Akten verknüpft werden — es ist kein spekulatives Token. Anders als typische NFTs betont es präparatgerechte Metadaten, Herkunft, ausdrückliche Lizenzierung und optionale physische Bindung. Nach taiwanischem Recht ist SAT nicht automatisch Währung nach dem Banking Act oder ein Wertpapier nach dem Securities and Exchange Act; irreführende Anlagewerbung bleibt untersagt.`)},{q:e(`台灣哪些法律可能適用於 SAT 交易？`,`Which Taiwan laws may apply to SAT transactions?`,`SAT取引に適用される可能性のある台湾の法律は？`,`Welche taiwanischen Gesetze können für SAT-Transaktionen gelten?`),a:e(`視個案可能涉及：《民法》（買賣、保管、所有權移轉）、《消費者保護法》（B2C 揭露與爭議）、《著作權法》（影像與文字）、《個人資料保護法》（採集者與 GPS 等）、《野生動物保育法》（保護物種產製品）、《文化資產保存法》（化石、考古、指定資產）、《植物防疫檢疫法》及進出口／海關相關規定。本頁不取代個案法律意見。`,`Depending on the case: Civil Code (sale, custody, title), Consumer Protection Act (B2C disclosure/disputes), Copyright Act, PDPA, Wildlife Conservation Act, Cultural Heritage Preservation Act, Plant Protection and Quarantine Act, and import/export/customs rules. This page does not replace case-specific legal advice.`,`案件により、民法（売買、保管、所有権）、消費者保護法（B2C開示・紛争）、著作権法、個人データ保護法、野生動物保育法、文化資産保存法、植物防疫検疫法、輸出入・通関規則が関わる場合があります。本ページは個別の法的助言の代替にはなりません。`,`Je nach Fall können gelten: Zivilgesetzbuch (Kauf, Verwahrung, Eigentum), Verbraucherschutzgesetz (B2C-Offenlegung und Streit), Urheberrechtsgesetz, PDPA, Wildtierschutzgesetz, Kulturerbe-Erhaltungsgesetz sowie Pflanzenschutz- und Quarantänerecht und Ein-/Ausfuhr- und Zollregeln. Diese Seite ersetzt keinen einzelfallbezogenen Rechtsrat.`)},{q:e(`CITES 與《名古屋議定書》如何適用？`,`How do CITES and the Nagoya Protocol apply?`,`CITESと名古屋議定書はどのように適用されますか？`,`Wie gelten CITES und das Nagoya-Protokoll?`),a:e(`CITES 規範附錄物種國際貿易，須由出口國／進口國主管機關核發許可；SAT 可記載許可摘要，但不代辦。CBD《名古屋議定書》規範遺傳資源與傳統知識利用之 ABS（事先知情同意 PIC、共同商定條件 MAT）；跨境研究或商業化前應完成 ABS 盡職調查。交易雙方及顧問負主要義務；平台示範環境不保證合法性。`,`CITES governs international trade in listed species via export/import permits—SAT may record summaries but does not obtain permits. The Nagoya Protocol governs ABS (PIC, MAT) for genetic resources and traditional knowledge—complete ABS due diligence before cross-border research or commercialization. Parties and advisors bear primary duties; the demo platform does not guarantee legality.`,`CITESはリスト種の国際取引を輸出／輸入許可で規制します。SATは概要を記録できますが、許可の取得は行いません。名古屋議定書は遺伝資源と伝統的知識のABS（PIC、MAT）を規定します。国境を越える研究・商用化前にABSデューデリジェンスを完了してください。主要義務は当事者とアドバイザーにあり、デモプラットフォームは合法性を保証しません。`,`CITES regelt den internationalen Handel gelisteter Arten über Ausfuhr- und Einfuhrgenehmigungen — SAT kann Kurzfassungen festhalten, holt Genehmigungen aber nicht ein. Das Nagoya-Protokoll regelt ABS (PIC, MAT) für genetische Ressourcen und traditionelles Wissen — schließen Sie die ABS-Sorgfaltsprüfung vor grenzüberschreitender Forschung oder Kommerzialisierung ab. Parteien und Beraterinnen bzw. Berater tragen die Hauptpflichten; die Demo-Plattform garantiert keine Rechtmäßigkeit.`)},{q:e(`「已驗證元資料」有法律效力嗎？`,`Does "verified metadata" have legal effect?`,`「検証済みメタデータ」には法的効力がありますか？`,`Haben „verifizierte Metadaten“ Rechtswirkung?`),a:e(`驗證表示平台工作流就緒度與資料一致性里程碑，不等同政府鑑定、公證或法院採信。它可協助盡職調查與引用，但學名、產地、年代、影像與實體一致性仍應自行查證文獻、標本館與主管機關紀錄。涉及訴訟或仲裁時，證據能力與證明力由法院或仲裁庭決定。`,`Verification marks platform readiness and consistency milestones—not government appraisal, notarization, or court adoption. It aids due diligence and citation, but taxonomy, locality, dates, and image–specimen match must still be verified independently. Admissibility and weight in litigation or arbitration are for courts or tribunals.`,`検証はプラットフォームの準備度と一貫性のマイルストーンを示し、政府鑑定、公証、裁判所の採用と同等ではありません。デューデリジェンスと引用に役立ちますが、学名、採集地、年代、画像と実物の一致は独自に確認する必要があります。訴訟・仲裁での証拠能力と証明力は裁判所または仲裁廷が判断します。`,`Die Verifizierung kennzeichnet Bereitschaft und Konsistenzmeilensteine der Plattform — keine staatliche Bewertung, Beurkundung oder gerichtliche Übernahme. Sie hilft bei Sorgfaltsprüfung und Zitation, aber Taxonomie, Fundort, Daten und die Übereinstimmung von Bild und Präparat müssen Sie weiterhin selbst prüfen. Beweisbarkeit und Beweiswert in Verfahren entscheiden Gerichte oder Schiedsgerichte.`)},{q:e(`買 SAT 是否取得標本著作權或所有權？`,`Does buying an SAT confer copyright or ownership of the specimen?`,`SATを購入すると標本の著作権や所有権を取得できますか？`,`Erwirbt der Kauf eines SAT Urheberrecht oder Eigentum am Präparat?`),a:e(`通常否。買方取得的是 listing 明示之數位紀錄與元資料使用權；著作權仍屬原權利人除非書面移轉。實體標本之所有權或保管權僅在 listing 明示「含實體標本」且雙方完成約定移交程序時才可能一併移轉；仍須符合野生動植物、文化資產及進出口法規。`,`Usually no. Buyers receive digital record and metadata usage per the listing; copyright stays with rights holders unless assigned in writing. Physical ownership or custody transfers only when the listing states physical binding and parties complete agreed handover—and still must comply with wildlife, heritage, and import/export laws.`,`通常はいいえ。買主が得るのはlistingに記載された範囲のデジタル記録とメタデータの利用権です。著作権は書面による譲渡がない限り原権利者に残ります。実物の所有権や保管権は、listingに実物紐付けが明記され、双方が合意した移転手続きを完了した場合にのみ移転し、野生生物、文化資産、輸出入法規の遵守が必要です。`,`In der Regel nein. Käuferinnen und Käufer erhalten Nutzungsrechte an digitaler Akte und Metadaten gemäß dem Angebot; das Urheberrecht bleibt bei den Rechteinhabern, sofern es nicht schriftlich übertragen wird. Physisches Eigentum oder Verwahrung gehen nur über, wenn das Angebot die physische Bindung ausdrücklich nennt und beide Seiten die vereinbarte Übergabe abschließen — und weiterhin Wildlife-, Kulturerbe- sowie Ein- und Ausfuhrrecht einhalten.`)},{q:e(`個資（採集者、GPS）如何處理？`,`How is personal data (collector, GPS) handled?`,`個人データ（採集者、GPS）はどのように扱われますか？`,`Wie werden personenbezogene Daten (Sammlerin bzw. Sammler, GPS) behandelt?`),a:e(`台灣《個人資料保護法》要求告知、特定目的、安全維護及當事人權利行使。精確 GPS、採集者姓名或原住民相關資訊應模糊化、限制存取或延遲公開。涉及歐盟資料主體時可能適用 GDPR。示範環境請勿輸入真實敏感個資；正式環境將適用 MCurator 隱私政策。`,`Taiwan PDPA requires notice, purpose limitation, security, and data-subject rights. Precise GPS, collector names, or indigenous-related data should be obfuscated, access-restricted, or delayed. EU subjects may trigger GDPR. Do not enter real sensitive data in the demo; production follows MCurator privacy policy.`,`台湾の個人データ保護法では、告知、目的限定、安全管理、データ主体の権利が求められます。正確なGPS、採集者名、先住民関連情報は曖昧化、アクセス制限、遅延公開を行うべきです。EUのデータ主体にはGDPRが適用される場合があります。デモでは実際の機微な個人情報を入力しないでください。本番環境ではMCuratorのプライバシーポリシーが適用されます。`,`Die taiwanische PDPA verlangt Hinweis, Zweckbindung, Sicherheit und Betroffenenrechte. Präzises GPS, Namen von Sammlerinnen und Sammlern oder indigene Angaben sollten unkenntlich gemacht, zugriffsbeschränkt oder verzögert veröffentlicht werden. Betroffene in der EU können die GDPR auslösen. Geben Sie in der Demo keine echten sensiblen Daten ein; in der Produktion gilt die Datenschutzrichtlinie von MCurator.`)},{q:e(`化石或考古標本有何特別規定？`,`Special rules for fossils or archaeological specimens?`,`化石や考古標本には特別な規定がありますか？`,`Gibt es besondere Regeln für Fossilien oder archäologische Präparate?`),a:e(`台灣《文化資產保存法》對古生物化石、考古遺物及指定文化資產之發掘、移出、買賣或出口可能有許可或禁止規定；SAT 登錄不取代主管機關程序。國際上部分國家對化石出口有專法或禁限令；跨境移動前應查核雙方法規與機構 deaccession 政策。`,`Taiwan's Cultural Heritage Preservation Act may require permits or prohibit trade/export of fossils, archaeological finds, and designated heritage—SAT registration does not replace authority procedures. Some countries restrict fossil export; check both jurisdictions and institutional deaccession policies before cross-border moves.`,`台湾の文化資産保存法では、化石、考古遺物、指定文化資産の発掘、移出、売買、輸出に許可や禁止がある場合があります。SAT登録は当局手続きの代替にはなりません。化石輸出を制限する国もあります。国境を越える移動前に双方の法規と機関のdeaccession方針を確認してください。`,`Das taiwanische Cultural Heritage Preservation Act kann Genehmigungen verlangen oder Handel bzw. Ausfuhr von Fossilien, archäologischen Funden und ausgewiesenem Kulturerbe untersagen — die SAT-Registrierung ersetzt keine Behördenverfahren. Manche Staaten beschränken die Fossilausfuhr; prüfen Sie vor grenzüberschreitender Verbringung beide Rechtsordnungen und die Deaccession-Richtlinie der Einrichtung.`)},{q:e(`可以商業使用 SAT 影像嗎？`,`Can I use SAT imagery commercially?`,`SAT画像を商用利用できますか？`,`Darf ich SAT-Bilder kommerziell nutzen?`),a:e(`僅在 listing 授權明示允許商業使用、改作或再授權時。台灣《著作權法》下，超出授權之重製、改作、散布、公開展示或商用可能構成侵權。國際上亦須遵守 Berne 最低標準及 CC 等授權條款；詳見各資產「權利與授權」分頁。`,`Only if the listing explicitly allows commercial use, adaptation, or sublicensing. Under Taiwan Copyright Act, reproduction, adaptation, distribution, or public display beyond license may infringe. Internationally, respect Berne minima and CC terms—see each asset Rights tab.`,`listingで商用利用、改作、再ライセンスが明示的に許可されている場合のみ可能です。台湾著作権法では、ライセンスを超える複製、改作、頒布、公開展示、商用利用は侵害となる場合があります。国際的にはベルヌ最低基準とCC条項を尊重してください。各アセットの「権利とライセンス」タブを参照してください。`,`Nur wenn das Angebot kommerzielle Nutzung, Bearbeitung oder Unterlizenzierung ausdrücklich erlaubt. Nach dem taiwanischen Copyright Act können Vervielfältigung, Bearbeitung, Verbreitung oder öffentliche Wiedergabe über die Lizenz hinaus eine Verletzung darstellen. International achten Sie die Mindeststandards von Berne und CC-Bedingungen — siehe den Reiter „Rechte und Lizenz“ jedes Assets.`)},{q:e(`如何正確引用 SAT？`,`How should I cite an SAT?`,`SATはどのように引用すべきですか？`,`Wie zitieren Sie ein SAT korrekt?`),a:e(`建議包含：SAT ID、學名、產地（若公開）、保管者、授權類型、存取日期、可解析 URL，以及上游 GBIF／館藏／文獻引用。學術出版應同時遵守期刊、DataCite 與機構引用政策；法庭或仲裁用途之證據形式須另依程序規則準備。`,`Include SAT ID, scientific name, locality (if public), custodian, license type, access date, resolvable URL, and upstream GBIF/collection/literature citations. Academic publishing should follow journal, DataCite, and institutional policies; legal proceedings require formats under procedural rules.`,`SAT ID、学名、採集地（公開時）、保管者、ライセンス種別、アクセス日、解決可能なURL、上流のGBIF／コレクション／文献引用を含めることを推奨します。学術出版は学術誌、DataCite、機関の方針に従ってください。法的手続きでは手続規則に基づく形式が必要です。`,`Geben Sie SAT-ID, wissenschaftlichen Namen, Fundort (falls öffentlich), Verwahrende, Lizenztyp, Zugriffsdatum, auflösbare URL und vorgelagerte GBIF-/Sammlungs-/Literaturzitate an. Akademische Publikationen sollten Zeitschriften-, DataCite- und institutionelle Richtlinien befolgen; gerichtliche Verfahren erfordern Formate nach Verfahrensregeln.`)},{q:e(`示範環境有法律約束力嗎？`,`Is the demo environment legally binding?`,`デモ環境には法的拘束力がありますか？`,`Ist die Demo-Umgebung rechtlich bindend?`),a:e(`否。示範資產、價格、驗證狀態、錢包與交易為測試資料，不構成要約或合約。正式上線後適用之服務條款、隱私政策、準據法（規劃為中華民國法律為主，跨境交易另依衝突法與條款約定）及爭議解決機制將另行公告。`,`No. Demo assets, prices, verification, wallets, and transactions are test data—not offers or contracts. Live terms, privacy policy, governing law (planned: primarily R.O.C. (Taiwan) law, with conflict-of-law rules for cross-border deals), and dispute resolution will be published at launch.`,`いいえ。デモの資産、価格、検証、ウォレット、取引はテストデータであり、申込みや契約を構成しません。正式な利用規約、プライバシーポリシー、準拠法（計画：主に中華民国（台湾）法、国境を越える取引は法の抵触規則と条項による）、紛争解決は公開時に公表されます。`,`Nein. Demo-Assets, Preise, Verifizierung, Wallets und Transaktionen sind Testdaten — keine Angebote und keine Verträge. Förmliche Nutzungsbedingungen, Datenschutzrichtlinie, anwendbares Recht (geplant: vorwiegend Recht der R.O.C. (Taiwan), bei grenzüberschreitenden Geschäften mit Kollisionsrecht und vereinbarten Klauseln) sowie Streitbeilegung werden bei der Einführung bekanntgegeben.`)},{q:e(`爭議、退貨與申訴如何處理？`,`Disputes, refunds, and appeals?`,`紛争、返品、申立はどう扱われますか？`,`Wie werden Streit, Erstattung und Einspruch behandelt?`),a:e(`示範無真實金流，無正式退貨。正式上線規劃：授權範圍爭議、元資料重大錯誤、實體標本損壞或未到貨、驗證申覆等流程；可能含暫停交割、第三方鑑定、調解或仲裁（依服務條款）。消費爭議可另依《消費者保護法》向消保官或消費爭議調解／仲裁機制申訴（若適用）。`,`Demo has no real payments or refunds. Live launch plans flows for license disputes, material metadata errors, physical damage/non-delivery, and verification appeals—possibly holds, third-party review, mediation, or arbitration per terms. Consumer disputes may use Taiwan Consumer Protection Act channels where applicable.`,`デモには実際の決済や返品はありません。本番公開後は、ライセンス紛争、重大なメタデータ誤り、実物の破損・未着、検証申立などの手続きを計画しています。決済保留、第三者審査、調停、仲裁を含む場合があります（利用規約による）。消費者紛争は適用される場合、台湾消費者保護法のチャネルを利用できます。`,`Die Demo hat keine echten Zahlungen und keine förmliche Erstattung. Für die Einführung sind Abläufe für Lizenzstreit, wesentliche Metadatenfehler, physischen Schaden oder Nichtlieferung sowie Verifizierungseinsprüche geplant — gegebenenfalls mit Zurückhaltung, Drittprüfung, Mediation oder Schiedsverfahren nach den Bedingungen. Verbraucherinnen und Verbraucher können, soweit anwendbar, Kanäle nach dem taiwanischen Consumer Protection Act nutzen.`)},{q:e(`SAT 與博物館館藏紀錄有何不同？`,`How is SAT different from a museum catalog?`,`SATは博物館のカタログとどう違いますか？`,`Worin unterscheidet sich SAT von einem Museumskatalog?`),a:e(`館藏系統是機構權威紀錄與 deaccession 程序載體；SAT 是面向授權流通、公眾引用與（可選）市場結算之數位身分層。兩者應以機構典藏號交叉引用，而非互相取代。館藏移出或借出仍須依《文化資產保存法》及館方政策。`,`Museum systems are institutional systems of record and deaccession workflows; SAT is the licensable digital layer for circulation, public citation, and optional marketplace settlement. Cross-reference catalog numbers—do not replace each other. Deaccession or loans still follow heritage law and museum policy.`,`博物館システムは機関の公式記録とdeaccession手続きの基盤です。SATは流通、公開引用、（任意の）マーケットプレイス決済のためのライセンス可能なデジタル層です。コレクション番号は相互参照し、互いに置き換えないでください。deaccessionや貸出は依然として文化財法と博物館方針に従います。`,`Museumssysteme sind die institutionelle Akte und der Deaccession-Ablauf; SAT ist die lizenzierbare digitale Schicht für Umlauf, öffentliche Zitation und optionale Marktplatz-Abwicklung. Katalognummern sollten querverwiesen werden — sie ersetzen einander nicht. Deaccession oder Leihen folgen weiterhin dem Kulturerberecht und der Museumsrichtlinie.`)},{q:e(`穩定幣或加密付款有何合規風險？`,`Compliance risks with stablecoin or crypto payments?`,`ステーブルコインや暗号資産決済のコンプライアンスリスクは？`,`Welche Compliance-Risiken bestehen bei Stablecoin- oder Krypto-Zahlungen?`),a:e(`正式環境若開放加密資產付款，可能涉及台灣金管會對虛擬資產平台之規範、洗錢防制法 AML/KYC、國際制裁篩查及稅務申報。示範環境為模擬，不觸發真實金流。賣家與買方應自行評估並遵守適用法令；平台將於上線前公告支援範圍與禁止用途。`,`Live crypto payments may trigger Taiwan FSC virtual-asset rules, AML/KYC under the Money Laundering Control Act, sanctions screening, and tax reporting. Demo payments are simulated. Parties must assess applicable law; supported scope and prohibited uses will be announced before launch.`,`本番の暗号資産決済には、台湾金管会の仮想資産規制、洗錢防制法のAML／KYC、制裁スクリーニング、税務申告が関わる場合があります。デモの支払いは模擬です。当事者は適用法を評価する必要があり、対応範囲と禁止用途は公開前に公表されます。`,`Echte Krypto-Zahlungen können Regelungen der taiwanischen FSC zu virtuellen Assets, AML/KYC nach dem Money Laundering Control Act, Sanktionsprüfungen und Steuererklärungen auslösen. Demo-Zahlungen sind simuliert. Die Parteien müssen das anwendbare Recht selbst prüfen; unterstützter Umfang und verbotene Zwecke werden vor der Einführung bekanntgegeben.`)},{q:e(`我可以把 SAT 當投資商品嗎？`,`Can I treat SAT as an investment?`,`SATを投資商品として扱えますか？`,`Darf ich SAT als Anlage behandeln?`),a:e(`不可以。平台不提供投資建議、不承諾增值或報酬率。依台灣法規，對不特定大眾宣稱保證獲利或暗示金融商品特性可能涉及行政或刑事責任。任何示範價格僅供 UI 測試。`,`No. No investment advice or promised returns. Under Taiwan law, public promises of guaranteed profit or implying financial-product characteristics may trigger administrative or criminal liability. Demo prices are for UI testing only.`,`いいえ。投資助言やリターンの約束はありません。台湾法では、不特定多数への利益保証や金融商品性の暗示は行政・刑事責任につながる場合があります。デモ価格はUIテスト用のみです。`,`Nein. Die Plattform gibt keine Anlageberatung und verspricht keine Wertsteigerung oder Rendite. Nach taiwanischem Recht können öffentliche Gewinnversprechen oder die Andeutung von Finanzprodukteigenschaften verwaltungs- oder strafrechtliche Haftung auslösen. Demo-Preise dienen nur der UI-Prüfung.`)},{q:e(`買 SAT 是否自動包含實體標本？`,`Does buying an SAT always include the physical specimen?`,`SAT購入には常に実物標本が含まれますか？`,`Enthält der Kauf eines SAT stets das physische Präparat?`),a:e(`否。僅 listing 明確標示含實體標本（physical binding）時才應一併移交保管權；移交仍須符合 CITES、檢疫、文化資產及雙方物流約定。`,`No. Physical custody transfers only when the listing explicitly states physical binding; handover must still comply with CITES, quarantine, heritage rules, and logistics agreements.`,`いいえ。listingに実物紐付け（physical binding）が明示されている場合のみ保管権が移転します。移転はCITES、検疫、文化資産法規、物流合意に従う必要があります。`,`Nein. Physische Verwahrung geht nur über, wenn das Angebot die physische Bindung ausdrücklich nennt; die Übergabe muss weiterhin CITES, Quarantäne, Kulturerberecht und die Logistikvereinbarung einhalten.`)},{q:e(`館員驗證與 SAT-MGS 有何差別？`,`Curator verification vs SAT-MGS grading?`,`キュレーター検証とSAT-MGSグレードの違いは？`,`Worin unterscheiden sich Kuratorprüfung und SAT-MGS-Bewertung?`),a:e(`SAT-MGS 為規則引擎自動建議分數；館員驗證為人工覆核里程碑。兩者均非政府認證；買方應一併審閱 provenance、許可摘要與權利分頁。`,`SAT-MGS is automated rule-engine scoring; curator verification is human-reviewed. Neither is government certification—buyers should also review provenance, permit summaries, and rights tabs.`,`SAT-MGSはルールエンジンによる自動スコアリングです。キュレーター検証は人手による再審です。いずれも政府認証ではありません。買主はprovenance、許可概要、権利タブも確認してください。`,`SAT-MGS ist eine automatische Regelmotor-Bewertung; die Kuratorprüfung ist eine menschliche Nachprüfung. Beides ist keine staatliche Zertifizierung — Käuferinnen und Käufer sollten Herkunft, Genehmigungskurzfassungen und den Reiter zu Rechten mitprüfen.`)},{q:e(`示範資料可以正式引用嗎？`,`Can demo data be cited formally?`,`デモデータを正式に引用できますか？`,`Dürfen Demo-Daten förmlich zitiert werden?`),a:e(`不建議。示範資產與交易為測試用途；正式研究或法律程序應引用已上線、權利清晰、可長期解析且 provenance 完整之 SAT 紀錄。`,`Not recommended. Demo assets are for testing; formal research or legal proceedings should cite live SAT records with clear rights, persistent resolution, and complete provenance.`,`推奨しません。デモ資産はテスト用です。正式な研究や法的手続きでは、権利が明確で永続的に解決可能かつprovenanceが完全な本番SAT記録を引用してください。`,`Nicht empfohlen. Demo-Assets dienen der Prüfung; förmliche Forschung oder Rechtsverfahren sollten live SAT-Akten mit klaren Rechten, dauerhafter Auflösung und vollständiger Herkunft zitieren.`)}],a=[{title:e(`1. 示範環境免責`,`1. Demo environment disclaimer`,`1. デモ環境の免責事項`,`1. Haftungsausschluss der Demo-Umgebung`),paragraphs:[e(`本 SAT 說明頁與市集介面為產品開發與教育示範用途。除非另有書面聲明，資產、價格、驗證狀態、交易紀錄、錢包地址與區塊鏈名稱均為虛構或測試資料，不構成要約、要約邀請或具約束力交易。`,`This SAT guide and marketplace UI are for product development and educational demonstration. Unless stated in writing, assets, prices, verification, transactions, wallet addresses, and network names are fictional or test data and do not constitute an offer, invitation to treat, or binding transaction.`,`本SATガイドとマーケットプレイスUIは製品開発と教育デモ用です。書面で別段の定めがない限り、資産、価格、検証、取引、ウォレットアドレス、ネットワーク名は架空またはテストデータであり、申込み、申込みの誘引、拘束力のある取引を構成しません。`,`Diese SAT-Erläuterung und die Marktplatz-Oberfläche dienen der Produktentwicklung und der Bildungsdemonstration. Sofern nicht schriftlich anders angegeben, sind Assets, Preise, Verifizierung, Transaktionen, Wallet-Adressen und Netzwerknamen fiktiv oder Testdaten und stellen weder ein Angebot noch eine Aufforderung zum Vertragsschluss noch ein bindendes Geschäft dar.`)]},{title:e(`2. 非法律／投資／稅務意見`,`2. No legal, investment, or tax advice`,`2. 法的・投資・税務助言ではありません`,`2. Keine Rechts-, Anlage- oder Steuerberatung`),paragraphs:[e(`MCurator 不提供法律、投資、報關、CITES 代辦或稅務意見。SAT 不得解釋為收益憑證、存款或保證獲利工具。使用者應自行諮詢律師、會計師、報關行及科學顧問。`,`MCurator does not provide legal, investment, customs, CITES agency, or tax advice. SAT must not be treated as yield instruments, deposits, or guaranteed-profit tools. Users should consult lawyers, accountants, customs brokers, and scientific advisors.`,`MCuratorは法律、投資、通関、CITES代行、税務の助言を提供しません。SATを利回り証書、預金、利益保証ツールとして扱ってはなりません。ユーザーは弁護士、会計士、通関業者、科学アドバイザーに相談してください。`,`MCurator erteilt keinen Rechts-, Anlage-, Zoll-, CITES-Vertretungs- oder Steuerberatung. SAT darf nicht als Ertragsinstrument, Einlage oder gewinnverbürgendes Werkzeug behandelt werden. Nutzerinnen und Nutzer sollten Rechtsanwältinnen und Rechtsanwälte, Steuerberatende, Zollmaklerinnen und Zollmakler sowie wissenschaftliche Beraterinnen und Berater hinzuziehen.`)]},{title:e(`3. 台灣法規遵循（摘要）`,`3. Taiwan regulatory compliance (summary)`,`3. 台湾の法規遵守（概要）`,`3. Taiwanische Rechtsbefolgung (Kurzfassung)`),paragraphs:[e(`使用者於台灣境內從事採集、持有、買賣、展示、出口或個資處理時，應自行遵守《野生動物保育法》《文化資產保存法》《個人資料保護法》《著作權法》《消費者保護法》《民法》及相關子法與主管機關函釋。平台不保證每筆交易已符合上述法令。`,`Users operating in Taiwan must comply with the Wildlife Conservation Act, Cultural Heritage Preservation Act, PDPA, Copyright Act, Consumer Protection Act, Civil Code, and related rules. The platform does not warrant that every transaction complies.`,`台湾で活動するユーザーは、野生動物保育法、文化資産保存法、個人データ保護法、著作権法、消費者保護法、民法および関連規則を遵守する必要があります。プラットフォームはすべての取引が法令に適合することを保証しません。`,`Wer in Taiwan sammelt, hält, kauft, verkauft, ausstellt, ausführt oder personenbezogene Daten verarbeitet, muss selbst den Wildlife Conservation Act, das Cultural Heritage Preservation Act, die PDPA, den Copyright Act, den Consumer Protection Act, den Civil Code sowie zugehörige Untergesetze und Behördenauslegungen einhalten. Die Plattform gewährleistet nicht, dass jede Transaktion diesen Vorschriften entspricht.`)]},{title:e(`4. 國際法規遵循（摘要）`,`4. International regulatory compliance (summary)`,`4. 国際法規遵守（概要）`,`4. Internationale Rechtsbefolgung (Kurzfassung)`),paragraphs:[e(`跨境標本或資料利用可能受 CITES、CBD／名古屋議定書 ABS、Berne／WIPO 著作權體系、歐盟 GDPR、目的地國禁限令及制裁法規約束。SAT 元資料對齊 Darwin Core 等標準以利科學互通，但不產生任何跨國許可。`,`Cross-border specimens or data may be subject to CITES, CBD/Nagoya ABS, Berne/WIPO copyright, EU GDPR, destination country restrictions, and sanctions. SAT metadata alignment with Darwin Core aids science but does not grant any cross-border permit.`,`国境を越える標本やデータには、CITES、CBD／名古屋ABS、ベルヌ／WIPO著作権、EU GDPR、目的地国の制限、制裁が適用される場合があります。SATメタデータのDarwin Core整合は科学に役立ちますが、国境を越える許可を付与するものではありません。`,`Grenzüberschreitende Präparate oder Daten können CITES, CBD/Nagoya-ABS, Urheberrecht nach Berne/WIPO, der EU-GDPR, Beschränkungen des Bestimmungsstaates und Sanktionsrecht unterliegen. Die Angleichung der SAT-Metadaten an Darwin Core dient der Wissenschaft, erteilt aber keine grenzüberschreitende Genehmigung.`)]},{title:e(`5. 科學與元資料準確性`,`5. Scientific & metadata accuracy`,`5. 科学的・メタデータの正確性`,`5. Wissenschaftliche und Metadaten-Genauigkeit`),paragraphs:[e(`平台不保證學名、年代、產地、影像與實體一致，或 provenance 完整無缺。科學結論與法律主張應自行查證文獻、標本館、主管機關與法院可接受之鑑定程序。`,`No warranty of taxonomy, dates, locality, image–specimen match, or complete provenance. Verify scientific and legal claims via literature, collections, authorities, and court-accepted expert procedures.`,`学名、年代、採集地、画像と実物の一致、provenanceの完全性について保証しません。文献、コレクション、当局、裁判所が認める鑑定手続きで科学的・法的主張を確認してください。`,`Die Plattform gewährleistet weder Taxonomie, Daten, Fundort, Übereinstimmung von Bild und Präparat noch vollständige Herkunft. Prüfen Sie wissenschaftliche und rechtliche Behauptungen anhand von Literatur, Sammlungen, Behörden und gerichtlich anerkannten Gutachtenverfahren.`)]},{title:e(`6. 智慧財產權`,`6. Intellectual property`,`6. 知的財産権`,`6. Geistiges Eigentum`),paragraphs:[e(`影像、描述、圖版與資料庫權利仍歸原權利人或授權人。超出 listing 或 CC 等授權範圍之重製、改作、散布、公開傳輸或商用可能構成台灣《著作權法》或國際公約下之侵權。`,`Rights in images, descriptions, plates, and database rights remain with rights holders. Reproduction, adaptation, distribution, communication, or commercial use beyond listing or CC license scope may infringe under Taiwan Copyright Act or international treaties.`,`画像、説明、図版、データベース権利は権利者に帰属します。listingまたはCCライセンスの範囲を超える複製、改作、頒布、公衆送信、商用利用は、台湾著作権法または国際条約上の侵害となる場合があります。`,`Rechte an Bildern, Beschreibungen, Tafeln und Datenbankrechte verbleiben bei den Rechteinhabern. Vervielfältigung, Bearbeitung, Verbreitung, öffentliche Wiedergabe oder kommerzielle Nutzung über den Umfang der Angebots- oder CC-Lizenz hinaus kann nach dem taiwanischen Copyright Act oder internationalen Verträgen eine Verletzung darstellen.`)]},{title:e(`7. 責任限制`,`7. Limitation of liability`,`第7条　免責および責任制限`,`7. Haftungsbeschränkung`),paragraphs:[e(`在法律允許範圍內，MCurator 對間接、衍生、資料遺失、監管處罰或第三人主張不負責；正式服務責任上限與除外事項將於上線條款載明。`,`To the extent permitted by law, MCurator is not liable for indirect, consequential, data-loss, regulatory penalty, or third-party claims; live caps and exclusions will be in launch terms.`,`法律で許される範囲で、MCuratorは間接的、派生的、データ損失、規制上の罰則、第三者の請求について責任を負いません。本番の上限と除外事項は公開時の条項に記載されます。`,`Soweit gesetzlich zulässig, haftet MCurator nicht für mittelbare, Folgeschäden, Datenverlust, behördliche Sanktionen oder Ansprüche Dritter; Obergrenzen und Ausschlüsse des förmlichen Dienstes werden in den Einführungsbedingungen genannt.`)]},{title:e(`8. 準據法與爭議解決（草案）`,`8. Governing law & disputes (draft)`,`8. 準拠法と紛争解決（草案）`,`8. Anwendbares Recht und Streitbeilegung (Entwurf)`),paragraphs:[e(`正式條款規劃以中華民國（台灣）法律為主要準據法；跨境交易另依衝突法、UNIDROIT 原則或條款約定之仲裁地及仲裁規則處理。本示範頁不產生合約關係。`,`Live terms plan primarily R.O.C. (Taiwan) law; cross-border deals may use conflict-of-law rules, UNIDROIT principles, or agreed arbitration seat and rules. This demo page creates no contract.`,`正式条項は主に中華民国（台湾）法を準拠法とする計画です。国境を越える取引は法の抵触規則、UNIDROIT原則、または合意された仲裁地・規則で処理される場合があります。本デモページは契約関係を生じません。`,`Die förmlichen Bedingungen planen vorwiegend Recht der R.O.C. (Taiwan); grenzüberschreitende Geschäfte können Kollisionsrecht, UNIDROIT-Grundsätze oder vereinbarten Schiedsort und Schiedsregeln nutzen. Diese Demo-Seite begründet kein Vertragsverhältnis.`)]},{title:e(`9. 條款變更`,`9. Changes to terms`,`9. 条項の変更`,`9. Änderungen der Bedingungen`),paragraphs:[e(`MCurator 保留更新本說明、市集規則及驗證標準之權利；涉及個資、收費或責任限制之重大變更將依正式條款合理通知。`,`MCurator may update this guide, marketplace rules, and verification standards; material changes affecting privacy, fees, or liability limits will be notified reasonably per live terms.`,`MCuratorは本ガイド、マーケットプレイス規則、検証基準を更新する権利を留保します。プライバシー、料金、責任制限に影響する重要な変更は、正式条項に従い合理的に通知されます。`,`MCurator behält sich vor, diese Erläuterung, Marktplatzregeln und Verifizierungsstandards zu aktualisieren; wesentliche Änderungen zu Datenschutz, Entgelten oder Haftungsgrenzen werden nach den förmlichen Bedingungen angemessen mitgeteilt.`)]}],o=[{term:`SAT`,def:e(`Scientific Asset Token — 科學資產代幣／登錄框架。`,`Scientific Asset Token — registration framework for scientific assets.`,`Scientific Asset Token — 科学アセットの登録フレームワーク。`,`Scientific Asset Token — Registrierungsrahmen für wissenschaftliche Assets.`)},{term:`CITES`,def:e(`華盛頓公約 — 規範附錄物種國際貿易；台灣以《野生動物保育法》實施。`,`Convention on International Trade in Endangered Species; implemented in Taiwan via the Wildlife Conservation Act.`,`絶滅のおそれのある野生動植物の種の国際取引に関する条約。台湾では野生動物保育法で実施。`,`Convention on International Trade in Endangered Species; in Taiwan über den Wildlife Conservation Act umgesetzt.`)},{term:e(`Nagoya Protocol`,`Nagoya Protocol`,`名古屋議定書`,`Nagoya-Protokoll`),def:e(`CBD 子公約 — 遺傳資源與傳統知識利用之 ABS（PIC／MAT）。`,`CBD protocol on ABS (PIC/MAT) for genetic resources and traditional knowledge.`,`遺伝資源と伝統的知識のABS（PIC／MAT）に関するCBD議定書。`,`CBD-Protokoll zu ABS (PIC/MAT) für genetische Ressourcen und traditionelles Wissen.`)},{term:e(`PDPA`,`PDPA`,`PDPA`,`PDPA`),def:e(`台灣《個人資料保護法》— 個資蒐集、處理與當事人權利。`,`Taiwan Personal Data Protection Act — collection, processing, and data-subject rights.`,`台湾個人データ保護法 — 収集、処理、データ主体の権利。`,`Taiwan Personal Data Protection Act — Erhebung, Verarbeitung und Betroffenenrechte.`)},{term:`Darwin Core`,def:e(`生物多樣性資料交換國際標準（dwc:）。`,`International biodiversity metadata standard (dwc:).`,`国際的な生物多様性メタデータ標準（dwc:）。`,`Internationaler Metadatenstandard für Biodiversität (dwc:).`)},{term:e(`Provenance`,`Provenance`,`由来`,`Herkunft`),def:e(`來源履歷 — 追加式保管與生命週期事件時間軸。`,`Append-only custody and lifecycle event timeline.`,`追記のみの保管とライフサイクルイベントのタイムライン。`,`Nur anhängbare Zeitachse von Verwahrung und Lebenszyklusereignissen.`)},{term:e(`Specimen Passport`,`Specimen Passport`,`標本パスポート`,`Präparat-Pass`),def:e(`標本護照 — 可攜式 SAT 身分與 QR 匯出入口。`,`Portable SAT identity with QR export entry point.`,`QRエクスポート入口を備えた携帯型SATアイデンティティ。`,`Tragbare SAT-Identität mit QR-Export-Einstieg.`)},{term:e(`Physical binding`,`Physical binding`,`実物紐付け`,`Physische Bindung`),def:e(`實體綁定 — 成交時數位 SAT 與實體標本保管權一併移交（須明示）。`,`Digital SAT and physical custody transfer together upon settlement (must be explicit).`,`成約時にデジタルSATと実物保管権を一緒に移転（明示必須）。`,`Digitales SAT und physische Verwahrung gehen bei der Abwicklung gemeinsam über (muss ausdrücklich sein).`)},{term:e(`Custody`,`Custody`,`保管権`,`Verwahrung`),def:e(`保管權 — 保存與管理責任，未必等同所有權。`,`Responsibility to hold and care—not always ownership.`,`保存・管理の責任 — 必ずしも所有権ではありません。`,`Pflicht zu Halten und Betreuen — nicht stets Eigentum.`)},{term:`ABS`,def:e(`Access and Benefit-Sharing — 遺傳資源獲取與惠益分享（名古屋議定書）。`,`Access and Benefit-Sharing under the Nagoya Protocol.`,`名古屋議定書に基づくアクセスと惠益分享。`,`Access and Benefit-Sharing nach dem Nagoya-Protokoll.`)},{term:`SAT-MGS`,def:e(`市集分級系統 — 規則引擎依照片與元資料完整度自動評分，非政府認證。`,`Marketplace grading — rule-engine score from photo and metadata completeness; not government certification.`,`マーケットプレイスグレーディング — 写真とメタデータ完成度によるルールエンジンスコア。政府認証ではありません。`,`Marktplatz-Bewertung — Regelmotor-Punktzahl aus Foto- und Metadaten-Vollständigkeit; keine staatliche Zertifizierung.`)},{term:e(`Mint`,`Mint`,`Mint`,`Prägung`),def:e(`鑄造 — 在平台建立 SAT ID 並初始化 provenance 之登錄動作。`,`Registering an SAT ID and initializing provenance on the platform.`,`プラットフォーム上でSAT IDを登録し、provenanceを初期化する操作。`,`Registrierung einer SAT-ID und Initialisierung der Herkunft auf der Plattform.`)},{term:e(`Hero-passport`,`Hero-passport`,`Hero-passport`,`Hero-Pass`),def:e(`護照主視覺照片 — 市集列表用之真實標本影像，非占位圖。`,`Primary passport photo for marketplace listings—real specimen imagery, not placeholders.`,`マーケットプレイス出品用のメイン写真 — 実物標本画像であり、プレースホルダーではありません。`,`Haupt-Passfoto für Marktplatz-Angebote — echte Präparataufnahmen, keine Platzhalter.`)},{term:e(`Completeness`,`Completeness`,`完成度`,`Vollständigkeit`),def:e(`完整度 — 規則引擎依必填欄位、影像與佐證文件計算之百分比。`,`Rule-engine percentage from required fields, imagery, and supporting documents.`,`必須項目、画像、補助書類から算出するルールエンジンのパーセンテージ。`,`Regelmotor-Prozentsatz aus Pflichtfeldern, Bildern und Belegen.`)},{term:e(`Verified metadata`,`Verified metadata`,`検証済みメタデータ`,`Verifizierte Metadaten`),def:e(`已驗證元資料 — 通過完整度、一致性與權利摘要檢查之科學欄位集合。`,`Scientific fields that passed completeness, consistency, and rights-summary checks.`,`完全性、一貫性、権利概要チェックを通過した科学フィールドの集合。`,`Wissenschaftliche Felder, die Prüfungen zu Vollständigkeit, Konsistenz und Rechtekurzfassung bestanden haben.`)}],s={title:e(`SAT 科學資產代幣 — 完整說明`,`Scientific Asset Tokens (SAT) — Full Guide`,`科学アセットトークン（SAT）— 完全ガイド`,`Wissenschaftlich Asset Tokens (SAT) — Voll Guide`),subtitle:e(`已驗證元資料、標本護照、來源履歷、授權與法律常見問答 — 完整參考`,`Verified metadata, specimen passports, provenance, licensing & legal FAQ — full reference`,`検証済みメタデータ、標本パスポート、由来履歴、ライセンス、法的FAQ — 完全リファレンス`,`Verified Metadaten, Präparat-Pässe, Herkunft, licensing & legal FAQ — full reference`),lastUpdated:e(`最後更新：2026-06-01`,`Last updated: 2026-06-01`,`最終更新：2026-06-01`,`Letzte aktualisiert: 2026-06-01`),teaserTitle:e(`科學資產代幣（SAT）`,`Scientific Asset Tokens (SAT)`,`科学アセットトークン（SAT）`,`Wissenschaftlich Asset Tokens (SAT)`),teaserLead:e(`已驗證元資料、標本護照、來源履歷、授權與法律常見問答 — 請見獨立說明頁。`,`Verified metadata, specimen passports, provenance, licensing, and legal FAQ — see the dedicated guide page.`,`検証済みメタデータ、標本パスポート、由来履歴、ライセンス、法的FAQ — 専用ガイドページをご覧ください。`,`Geprüfte Metadaten, Präparat-Pässe, Herkunft, Lizenzierung und rechtliche FAQ. Siehe die eigene Leitfadenseite.`),topicMetadata:e(`已驗證元資料`,`Verified metadata`,`検証済みメタデータ`,`Verifizierte Metadaten`),topicPassport:e(`標本護照`,`Specimen passport`,`標本パスポート`,`Präparat-Pass`),topicProvenance:e(`來源履歷`,`Provenance`,`由来履歴`,`Herkunft`),topicLicensing:e(`授權`,`Licensing`,`ライセンス`,`Lizenzierung`),topicLegalFaq:e(`法律常見問答`,`Legal FAQ`,`法的FAQ`,`Rechtliche FAQ`),sidebarChapters:e(`章節`,`Chapters`,`章`,`Kapitel`),openFullGuide:e(`開啟完整 SAT 說明`,`Open full SAT guide`,`SAT完全ガイドを開く`,`Öffnen full SAT guide`),demoBanner:e(`本頁與市集介面目前為產品示範（Mock）環境：無真實上鏈、無實際金流結算、元資料與驗證狀態僅供流程測試。正式上線前將另行公告適用之服務條款、隱私政策與交易規則。`,`This page and the marketplace UI run in a product demo (mock) environment: no live on-chain settlement, no real payment processing, and metadata or verification states are for workflow testing only. Binding terms, privacy policy, and trading rules will be published before any production launch.`,`本ページとマーケットプレイスUIは製品デモ（モック）環境です。実際のオンチェーン決済や金銭処理はなく、メタデータと検証状態はワークフロー検証用のみです。本番公開前に、適用される利用規約・プライバシーポリシー・取引ルールを別途公表します。`,`Diese Seite und die Marktplatz-Oberfläche laufen in einer Produktdemo (Mock): keine echte On-Chain-Abwicklung, keine echte Zahlungsabwicklung. Metadaten und Prüfstatus dienen nur dem Workflow-Test. Verbindliche Nutzungsbedingungen, Datenschutzerklärung und Handelsregeln werden vor dem Produktionsstart veröffentlicht.`),toc:e(`目錄`,`Contents`,`目次`,`Inhalt`),faqTitle:e(`常見問答（FAQ）`,`Frequently asked questions (FAQ)`,`よくある質問（FAQ）`,`Häufig gestellte Fragen (FAQ)`),legalTitle:e(`法律聲明與免責`,`Legal notices & disclaimers`,`法的声明と免責事項`,`Rechtliche Hinweise und Haftungsausschlüsse`),glossaryTitle:e(`名詞解釋`,`Glossary`,`用語集`,`Glossar`),backToMarket:e(`返回市集`,`Back to marketplace`,`マーケットプレイスに戻る`,`Zurück zum Marktplatz`),contactTitle:e(`聯絡與正式文件`,`Contact & official documents`,`お問い合わせと公式文書`,`Kontakt und amtliche Dokumente`),contactBody:e(`正式服務條款、隱私政策與爭議申訴流程將於上線時提供。示範階段問題可透過 App 內「關於」或 support@mcurator.app 聯繫。`,`Official terms, privacy policy, and dispute procedures will ship at launch. For demo-phase questions, use in-app About or support@mcurator.app.`,`正式な利用規約、プライバシーポリシー、紛争申立手続きは本番公開時に提供します。デモ段階のお問い合わせはアプリ内「About」または support@mcurator.app までご連絡ください。`,`Förmliche Nutzungsbedingungen, Datenschutzrichtlinie und Streitverfahren erscheinen zum Start. Fragen zur Demo über „Über“ in der App oder support@mcurator.app.`)};function c(e,t,n,r,i){return{id:e,title:t,paragraphs:n,bullets:r,steps:i}}var l=[...r,c(`physical`,e(`實體標本與 CITES`,`Physical specimens & CITES`,`実物標本とCITES`,`Physische Präparate und CITES`),[e(`若上架標示「含實體標本（physical specimen binding）」，表示 SAT 成交時，數位 SAT 紀錄與實體標本之保管權應一併移交買方（或買方指定之受託保管人），除非 listing 或合約另有載明。運送、包裝、保險、海關申報、CITES 許可證申請、入館審查與長期保存條件，均須由交易雙方或各自委託之物流／法律顧問另行約定。`,`When a listing states physical specimen binding, SAT settlement should transfer custody of both the digital SAT and the physical specimen to the buyer (or their custodian) unless stated otherwise. Shipping, packing, insurance, customs, CITES permits, accession review, and storage must be agreed separately by the parties or their agents.`,`出品に「実物標本付き（physical specimen binding）」と表示されている場合、SAT成約時にデジタルSAT記録と実物標本の保管権は、listingまたは契約に別段の定めがない限り、買主（または指定の受託保管者）へ移転する必要があります。輸送、梱包、保険、通関申告、CITES許可証申請、収蔵審査、長期保存条件は、取引当事者または委託する物流・法律顧問が別途合意する必要があります。`,`Wenn ein Angebot die Bindung an ein physisches Präparat ausweist, soll die SAT-Abwicklung die Verwahrung des digitalen SAT und des physischen Präparats an den Käufer oder dessen Verwahrer übertragen, sofern nichts anderes steht. Versand, Verpackung, Versicherung, Zoll, CITES-Genehmigungen, Zugangsprüfung und Lagerung vereinbaren die Parteien oder ihre Beauftragten gesondert.`),e(`買賣雙方有義務自行確認物種是否受 CITES、IUCN 紅色名錄、國內野生動植物保護法、化石或文化資產法規等約束；平台示範環境不提供法律意見，也不保證任何跨國運送之合法性。`,`Both parties must confirm CITES, IUCN Red List status, domestic wildlife laws, fossil or cultural heritage rules, etc. The demo platform does not provide legal advice or guarantee cross-border legality.`,`売買双方は、CITES、IUCNレッドリスト、国内の野生動植物保護法、化石・文化財関連法規などの適用を各自確認する義務があります。プラットフォームのデモ環境は法的助言を提供せず、国際輸送の合法性も保証しません。`,`Beide Seiten müssen CITES, den Status auf der IUCN-Roten Liste, nationale Artenschutzregeln sowie Vorgaben zu Fossilien oder Kulturerbe selbst prüfen. Die Demo-Plattform gibt keine Rechtsberatung und garantiert keine grenzüberschreitende Legalität.`)],[e(`結帳 UI 會標示「SAT + 實體」與移交提醒`,`Checkout UI flags "SAT + physical" and transfer reminders`,`チェックアウトUIに「SAT＋実物」と移転リマインダーを表示`,`Die Kasse kennzeichnet „SAT + physisch“ und erinnert an die Übergabe.`),e(`賣方須在 listing 勾選 hasPhysicalSpecimen 與移交說明`,`Sellers must set hasPhysicalSpecimen and transfer notes on the listing`,`売主はlistingでhasPhysicalSpecimenと移転説明を設定する必要があります`,`Verkäufer müssen hasPhysicalSpecimen und Übertragungshinweise in der Anzeige angeben.`),e(`買方應保留 provenance 與許可證副本以備稽核`,`Buyers should retain provenance and permit copies for audit`,`買主は監査用にprovenanceと許可証の写しを保管してください`,`Käufer sollen Herkunft und Genehmigungskopien für die Prüfung aufbewahren.`)]),c(`verification`,e(`驗證、SAT-MGS 與館員審查`,`Verification, SAT-MGS & curator review`,`検証、SAT-MGS、キュレーター審査`,`Prüfung, SAT-MGS und kuratorische Prüfung`),[e(`驗證狀態（如 Curator verified、SAT graded、Provenance complete）表示該資產在平台工作流中已達特定資料完整度或審查里程碑；不等同於第三方公證或學術期刊同儕審查。`,`Verification labels (e.g., Curator verified, SAT graded, Provenance complete) mark workflow milestones—not third-party notarization or journal peer review.`,`検証ステータス（Curator verified、SAT graded、Provenance completeなど）は、プラットフォームのワークフローで特定のデータ完成度または審査マイルストーンに到達したことを示します。第三者公証や学術誌の査読と同等ではありません。`,`Prüfkennzeichen, zum Beispiel vom Kurator geprüft, SAT bewertet, Herkunft vollständig, markieren Ablaufmeilensteine. Sie sind keine notarielle Beglaubigung und keine Begutachtung einer Fachzeitschrift.`),e(`SAT-MGS（Marketplace Grading System）以規則引擎評估照片清晰度、診斷特徵可見度、後設資料完整度等，產生系統建議等級；正式等級可由館員覆核。管理員可透過 SAT-MGS 後台提交或調整評分（示範）。`,`SAT-MGS applies rule-based scoring for photo clarity, visible diagnostic features, metadata completeness, etc.; official grades may be curator-reviewed. Admins can submit or adjust grades via the SAT-MGS console (demo).`,`SAT-MGS（Marketplace Grading System）はルールエンジンで写真の鮮明度、診断形質の可視性、メタデータの完成度などを評価し、システム推奨グレードを生成します。正式グレードはキュレーターが再審できます。管理者はSAT-MGSコンソールから評価の提出・調整が可能です（デモ）。`,`SAT-MGS bewertet nach Regeln Schärfe, sichtbare Diagnosemerkmale, Vollständigkeit der Metadaten und weiteres. Förmliche Noten kann ein Kurator prüfen. Die Verwaltung kann Noten über die SAT-MGS-Konsole einreichen oder anpassen (Demo).`)],[e(`照片：清晰度、尺度標、標本取向`,`Photos: clarity, scale bar, specimen orientation`,`写真：鮮明度、スケールバー、標本の向き`,`Photos: clarity, scale bar,Präparat orientation`),e(`資料：學名、產地、日期、採集者、分類階層`,`Data: scientific name, locality, date, collector, taxonomy`,`データ：学名、採集地、日付、採集者、分類階層`,`Data:wissenschaftlich name,Fundort, date,Sammler,Taxonomie`),e(`來源：provenance 節點數量與關鍵事件覆蓋`,`Provenance: node count and coverage of key events`,`由来：provenanceノード数と主要イベントの網羅`,`Herkunft: Knotenzahl und Abdeckung der zentralen Ereignisse`)]),c(`payments`,e(`付款與結帳`,`Payments & checkout`,`支払いとチェックアウト`,`Zahlungen und Kasse`),[e(`賣家在上架時勾選可接受之付款方式，例如信用卡、銀行匯款、USDC／USDT／ETH 等。買方結帳時僅能選擇該 listing 允許之方式。示範環境中之付款為模擬流程，不會實際扣款或移轉加密資產。`,`Sellers select accepted payment methods when listing—e.g., card, bank transfer, USDC / USDT / ETH. Buyers can only choose methods allowed for that listing. Demo payments are simulated with no real charges or crypto transfers.`,`売主は出品時にクレジットカード、銀行振込、USDC／USDT／ETHなどの受け入れ可能な支払い方法を選択します。買主はそのlistingで許可された方法のみ選択できます。デモ環境の支払いは模擬であり、実際の課金や暗号資産の移転は行われません。`,`Verkäufer wählen beim Anbieten die akzeptierten Zahlungswege, zum Beispiel Karte, Überweisung, USDC, USDT oder ETH. Käufer können nur Wege wählen, die das Angebot erlaubt. Demozahlungen sind simuliert, ohne echte Belastung oder Krypto-Übertragung.`),e(`成交後，系統更新保管人並追加 provenance「Acquired」或「Transferred」事件。含實體標本者，數位成交與實體物流應分開追蹤，避免混淆。`,`After settlement, the system updates the custodian and appends an Acquired or Transferred provenance event. For physical specimens, digital settlement and logistics should be tracked separately.`,`成約後、システムは保管者を更新し、provenanceに「Acquired」または「Transferred」イベントを追加します。実物標本付きの場合、デジタル成約と実物流送は別々に追跡し、混同を避けてください。`,`Nach der Abwicklung aktualisiert das System den Verwahrer und hängt ein Herkunftsereignis Acquired oder Transferred an. Bei physischen Präparaten sind digitale Abwicklung und Logistik getrennt zu führen.`)]),c(`roles`,e(`角色與責任`,`Roles & responsibilities`,`役割と責任`,`Rollen und Verantwortung`),[e(`不同參與者在 SAT 生態中負有不同義務。以下為示範工作流中的典型分工；正式上線後可能依機構合約調整。`,`Participants have different obligations in the SAT ecosystem. Below is typical demo workflow division; live launch may vary per institutional agreements.`,`SATエコシステムでは参加者ごとに異なる義務があります。以下はデモワークフローにおける典型的な分担です。本番公開後は機関契約により調整される場合があります。`,`Teilnehmende haben im SAT-Ökosystem unterschiedliche Pflichten. Unten steht die typische Aufteilung der Demo. Der echte Start kann je nach Institutionsvertrag abweichen.`)],[e(`賣方／機構：資料正確性、授權明示、付款方式、實體移交條款`,`Seller / institution: data accuracy, license disclosure, payments, physical terms`,`売主／機関：データの正確性、ライセンス明示、支払い方法、実物移転条件`,`Seller / institution: Daten accuracy, Lizenz disclosure, payments, physical terms`),e(`買方：遵守授權、自行確認法規、保管與引用 SAT ID`,`Buyer: honor license, confirm regulations, custody and citation of SAT ID`,`買主：ライセンス遵守、法規の自己確認、保管とSAT IDの引用`,`Käufer: Lizenz einhalten, Vorschriften selbst prüfen, Verwahrung und Zitierung der SAT-ID`),e(`館員／管理員：覆核驗證、SAT-MGS、爭議升級（示範）`,`Curator / admin: verification review, SAT-MGS, dispute escalation (demo)`,`キュレーター／管理者：検証の再審、SAT-MGS、紛争エスカレーション（デモ）`,`Kurator oder Verwaltung: Prüfung, SAT-MGS, Eskalation von Streitfällen (Demo)`),e(`平台：提供登錄與追溯介面，不提供投資建議或法律代理`,`Platform: registration and traceability UI—not investment advice or legal agency`,`プラットフォーム：登録とトレーサビリティUIを提供。投資助言や法的代理は行いません`,`Plattform: Oberfläche für Registrierung und Rückverfolgung. Keine Anlageberatung und keine Rechtsvertretung.`)]),c(`standards`,e(`資料標準與互通`,`Data standards & interoperability`,`データ標準と相互運用`,`Datenstandards und Interoperabilität`),[e(`MCurator 規劃使 SAT 元資料可對齊生物多樣性與館藏社群常用標準，例如 Darwin Core（ dwc: ）、ABCD 與 Dublin Core 精簡欄位，以利匯入 GBIF、機構典藏系統或研究資料庫。`,`MCurator plans SAT metadata alignment with Darwin Core, ABCD, and Dublin Core subsets for export to GBIF, collection systems, or research databases.`,`MCuratorはSATメタデータを生物多様性・コレクション分野の標準（Darwin Core、ABCD、Dublin Coreのサブセットなど）に整合し、GBIF、機関コレクションシステム、研究データベースへのエクスポートを計画しています。`,`MCurator plant, SAT-Metadaten an Teilmengen von Darwin Core, ABCD und Dublin Core auszurichten, für den Export nach GBIF, in Sammlungssysteme oder Forschungsdatenbanken.`),e(`示範環境已支援 QR、CSV、JSON 匯出（依資產就緒度）。正式環境將公告欄位對照表與 API 版本策略。`,`The demo supports QR, CSV, and JSON export (per asset readiness). Live environments will publish field mapping tables and API versioning.`,`デモ環境ではQR、CSV、JSONのエクスポートに対応しています（アセットの準備状況による）。本番環境ではフィールド対応表とAPIバージョン戦略を公表します。`,`Die Demo unterstützt den Export als QR, CSV und JSON, je nach Bereitschaft des Assets. Live-Umgebungen veröffentlichen Feldzuordnungen und die API-Versionierung.`)]),c(`privacy`,e(`隱私與敏感物種`,`Privacy & sensitive species`,`プライバシーと敏感種`,`Datenschutz & sensibel Art`),[e(`採集者姓名、精確 GPS、洞穴或稀有物種棲地等欄位可能涉及個資或物種安全。上架時應依機構政策做模糊化、權限控制或延遲公開。示範環境請勿輸入真實敏感個資。`,`Collector names, precise GPS, cave or rare-species localities may implicate privacy or species security. Obfuscate, restrict access, or delay publication per institutional policy. Do not enter real sensitive data in the demo.`,`採集者名、正確なGPS、洞窟や希少種の生息地などの項目は、個人情報や種の保全に関わる場合があります。出品時は機関方針に従い、曖昧化・アクセス制限・公開遅延を行ってください。デモ環境では実際の機微な個人情報を入力しないでください。`,`Namen von Sammlern, genaue GPS-Angaben sowie Höhlen- oder Seltenarten-Fundorte können Datenschutz oder Artenschutz berühren. Verschleiern Sie die Angaben, beschränken Sie den Zugriff oder verzögern Sie die Veröffentlichung gemäß institutioneller Richtlinie. Geben Sie in der Demonstration keine echten sensiblen Daten ein.`),e(`正式環境將適用 MCurator 隱私政策與資料主體權利流程；本說明頁不取代隱私政策全文。`,`Production will follow MCurator's privacy policy and data-subject procedures; this guide does not replace the full privacy policy.`,`本番環境ではMCuratorのプライバシーポリシーとデータ主体の権利手続きが適用されます。本ガイドはプライバシーポリシー全文の代替にはなりません。`,`In der Produktivumgebung gelten die Datenschutzrichtlinie von MCurator und die Verfahren für betroffene Personen. Diese Seite ersetzt die vollständige Datenschutzrichtlinie nicht.`)]),c(`disputes`,e(`爭議、退貨與申訴（草案）`,`Disputes, refunds & appeals (draft)`,`紛争、返品、申立（草案）`,`Disputes, refunds & appeals (Entwurf)`),[e(`示範環境不提供真實金流，因此無正式退貨機制。正式上線後，規劃包含：授權範圍爭議、元資料重大錯誤、實體標本損壞或未到貨、驗證等級申覆等流程；可能含暫停交割、第三方鑑定與仲裁條款（以服務條款為準）。`,`The demo has no real payments, so no formal refunds. After launch, planned flows cover license disputes, material metadata errors, physical damage or non-delivery, and grade appeals—possibly including settlement holds, third-party review, and arbitration (per terms of service).`,`デモ環境では実際の決済がないため、正式な返品制度はありません。本番公開後は、ライセンス範囲の紛争、メタデータの重大な誤り、実物標本の破損・未着、検証グレードの申立などの手続きを計画しています。決済保留、第三者鑑定、仲裁条項を含む場合があります（利用規約に準拠）。`,`Die Demo hat keine echten Zahlungen und damit keine förmliche Erstattung. Nach dem Start sind Abläufe für Lizenzstreit, wesentliche Metadatenfehler, physischen Schaden oder Nichtlieferung und Noteneinsprüche geplant, gegebenenfalls mit Zurückhaltung der Abwicklung, Drittprüfung und Schiedsverfahren nach den Nutzungsbedingungen.`)]),c(`ecology`,e(`生態回饋規劃`,`Ecology commitment (planned)`,`エコロジー還元の計画`,`Ökologische Rückführung (geplant)`),[e(`若未來提供鏈上結算，實際網路手續費如何分配（含保育專案）將以正式公告為準。示範環境不產生可分配的網路手續費，也不是募資或代幣銷售。`,`If on-chain settlement ships, how actual network charges are allocated (including conservation projects) will be published in a formal notice. The demo generates no allocatable network charges and is not a token sale.`,`オンチェーン決済が提供される場合、実際のネットワーク手数料の配分（保全プロジェクトを含む）は正式発表に従います。デモ環境では配分可能なネットワーク手数料は発生せず、資金調達やトークン販売でもありません。`,`Falls eine On-Chain-Abwicklung bereitgestellt wird, richtet sich die Verteilung tatsächlicher Netzgebühren (einschließlich Naturschutzprojekte) nach einer förmlichen Bekanntgabe. Die Demo erzeugt keine zu verteilenden Netzgebühren und ist kein Token-Verkauf.`)]),c(`workflow`,e(`典型流程（示範）`,`Typical workflow (demo)`,`典型的なフロー（デモ）`,`Typischer Ablauf (Demo)`),[],void 0,[{title:e(`1. 登錄 SAT`,`1. Register SAT`,`1. SATを登録`,`1. SAT registrieren`),body:e(`建立 SAT ID、上傳或連結標本影像、填寫學名、產地、採集者與分類資訊；初始化 provenance。`,`Create SAT ID, attach imagery, enter taxonomy, locality, collector, and classification; initialize provenance.`,`SAT IDを作成し、標本画像をアップロードまたはリンク、学名・採集地・採集者・分類情報を入力し、provenanceを初期化します。`,`SAT-ID anlegen, Bilder anfügen, Taxonomie, Fundort, Sammler und Klassifikation eintragen und die Herkunft initialisieren.`)},{title:e(`2. 驗證與分級`,`2. Verify & grade`,`2. 検証とグレード付け`,`2. Prüfen und benoten`),body:e(`館員或規則引擎審查資料完整度；必要時補件。`,`Curator or rule engine reviews completeness; supplementary documents if needed.`,`キュレーターまたはルールエンジンがデータの完成度を審査します。必要に応じて追加資料を求めます。`,`Kurator oder Regelwerk prüft die Vollständigkeit. Bei Bedarf weitere Unterlagen.`)},{title:e(`3. 上架`,`3. List`,`3. 出品`,`3. Anbieten`),body:e(`賣家設定價格、授權、是否含實體標本、付款方式。`,`Seller sets price, license, physical binding, and payment methods.`,`売主が価格、ライセンス、実物標本の有無、支払い方法を設定します。`,`Seller sets price, license, physical binding, und payment methods.`)},{title:e(`4. 取得與移交`,`4. Acquire & transfer`,`4. 取得と移転`,`4. Acquire und transfer`),body:e(`成交後更新保管人、追加 provenance 事件；含實體者另議物流與許可。`,`After settlement, update custodian and append provenance; physical transfers need logistics and permits.`,`成約後に保管者を更新し、provenanceイベントを追加します。実物付きの場合は物流と許可を別途手配します。`,`After settlement, aktualisieren custodian und append Herkunft; physical transfers need logistics und permits.`)},{title:e(`5. 引用與匯出`,`5. Cite & export`,`5. 引用とエクスポート`,`5. Cite &Exportieren`),body:e(`依授權引用 SAT ID；匯出 QR／CSV／JSON 供研究或教學。`,`Cite the SAT ID under license; export QR / CSV / JSON for research or teaching.`,`ライセンスに従いSAT IDを引用し、研究・教育用にQR／CSV／JSONをエクスポートします。`,`Cite SAT ID under Lizenz; Exportieren QR / CSV / JSON für Forschung oder teaching.`)}])],u=i,d=a,f=o;s.teaserTitle,s.topicMetadata,s.topicPassport,s.topicProvenance,s.topicLicensing,s.topicLegalFaq;var p=`/marketplace/about`;function m(e){let n=n=>t(e,n);return{title:n(s.title),subtitle:n(s.subtitle),lastUpdated:n(s.lastUpdated),demoBanner:n(s.demoBanner),toc:n(s.toc),faqTitle:n(s.faqTitle),legalTitle:n(s.legalTitle),glossaryTitle:n(s.glossaryTitle),backToMarket:n(s.backToMarket),contactTitle:n(s.contactTitle),contactBody:n(s.contactBody),teaserTitle:n(s.teaserTitle),teaserLead:n(s.teaserLead),openFullGuide:n(s.openFullGuide),sections:l.map(e=>({id:e.id,title:n(e.title),paragraphs:e.paragraphs.map(n),bullets:e.bullets?.map(n),...`steps`in e&&e.steps?{steps:e.steps.map(e=>({title:n(e.title),body:n(e.body)}))}:{}})),faq:u.map(e=>({q:n(e.q),a:n(e.a)})),legal:d.map(e=>({title:n(e.title),paragraphs:e.paragraphs.map(n)})),glossary:f.map(e=>({term:typeof e.term==`string`?e.term:n(e.term),def:n(e.def)}))}}function h(e){let n=n=>t(e,n);return{title:n(s.teaserTitle),lead:n(s.teaserLead),openFullGuide:n(s.openFullGuide)}}export{m as n,h as r,p as t};